const localEndings={de:['Bitte prüfen Sie die aktuellen Angaben vor der Zahlung.','Bewahren Sie die Nachweise für den späteren Vergleich auf.','Entscheiden Sie erst, wenn die sichtbaren Informationen passen.'],fr:['Vérifiez les informations actuelles avant de payer.','Conservez les preuves pour une comparaison ultérieure.','Décidez seulement lorsque les informations visibles concordent.'],es:['Revisa la información actual antes de pagar.','Guarda las pruebas para compararlas después.','Decide solo cuando la información visible coincida.'],it:['Controlla le informazioni aggiornate prima di pagare.','Conserva le prove per confrontarle in seguito.','Decidi solo quando le informazioni visibili coincidono.'],pt:['Consulte as informações atuais antes de pagar.','Guarde as provas para comparar mais tarde.','Decida apenas quando as informações visíveis coincidirem.'],nl:['Controleer de actuele informatie voordat u betaalt.','Bewaar het bewijs voor een latere vergelijking.','Beslis pas wanneer de zichtbare informatie overeenkomt.'],pl:['Sprawdź aktualne informacje przed płatnością.','Zachowaj dowody do późniejszego porównania.','Podejmij decyzję dopiero, gdy widoczne informacje się zgadzają.'],sv:['Kontrollera aktuell information före betalning.','Spara underlaget för senare jämförelse.','Bestäm dig först när den synliga informationen stämmer.']};
