const localDetailSentences={
  de:['Vergleichen Sie die sichtbaren Angaben mit dem gespeicherten Ausgangsnachweis.','Notieren Sie Variante, Datum und die Informationen, auf denen die Entscheidung beruht.','Aktuelle Regeln und verfügbare Optionen können sich ändern und müssen vor dem nächsten Schritt geprüft werden.','Treffen Sie die Entscheidung erst, wenn Quelle, sichtbare Belege und der aktuelle Status zusammenpassen.','Eine klare Dokumentation hilft, Produkt-, Lager- und Paketfragen getrennt zu beurteilen.'],
  fr:['Comparez les informations visibles avec la référence enregistrée.','Conservez la variante, la date et les éléments utilisés pour votre décision.','Les règles et options disponibles peuvent changer : vérifiez-les avant l’étape suivante.','Décidez seulement lorsque la source, les preuves visibles et le statut actuel concordent.','Un dossier clair aide à distinguer les questions de produit, d’entrepôt et de colis.'],
  es:['Compara la información visible con la referencia que guardaste.','Conserva la variante, la fecha y los datos utilizados para tomar la decisión.','Las reglas y opciones disponibles pueden cambiar; revísalas antes del siguiente paso.','Decide solo cuando la fuente, las pruebas visibles y el estado actual coincidan.','Un registro claro ayuda a separar cuestiones de producto, almacén y paquete.'],
  it:['Confronta le informazioni visibili con il riferimento salvato.','Conserva variante, data e dettagli usati per prendere la decisione.','Regole e opzioni disponibili possono cambiare: controllale prima del passaggio successivo.','Decidi solo quando fonte, prove visibili e stato attuale coincidono.','Una documentazione chiara aiuta a distinguere le questioni di prodotto, magazzino e pacco.'],
  pt:['Compare as informações visíveis com a referência guardada.','Guarde a variante, a data e os dados usados para tomar a decisão.','As regras e opções disponíveis podem mudar; confirme-as antes do passo seguinte.','Decida apenas quando a origem, as provas visíveis e o estado atual coincidirem.','Um registo claro ajuda a separar questões de produto, armazém e encomenda.'],
  nl:['Vergelijk de zichtbare informatie met de opgeslagen referentie.','Bewaar de variant, datum en gegevens waarop de beslissing is gebaseerd.','Beschikbare regels en opties kunnen veranderen; controleer ze vóór de volgende stap.','Beslis pas wanneer bron, zichtbaar bewijs en actuele status overeenkomen.','Een duidelijk dossier helpt product-, magazijn- en pakketvragen te onderscheiden.'],
  pl:['Porównaj widoczne informacje z zapisanym punktem odniesienia.','Zachowaj wariant, datę i dane użyte do podjęcia decyzji.','Dostępne zasady i opcje mogą się zmieniać; sprawdź je przed następnym krokiem.','Podejmij decyzję dopiero, gdy źródło, widoczne dowody i bieżący status są zgodne.','Jasna dokumentacja pomaga rozdzielić kwestie produktu, magazynu i paczki.'],
  sv:['Jämför synlig information med det sparade underlaget.','Spara variant, datum och uppgifter som användes för beslutet.','Tillgängliga regler och alternativ kan ändras; kontrollera dem före nästa steg.','Bestäm dig först när källa, synliga underlag och aktuell status stämmer.','Tydlig dokumentation hjälper dig att skilja produkt-, lager- och paketfrågor åt.']
};
function sourceDataNode(node){return Boolean(node?.parentElement?.closest('.product,.find,.thumbs,[data-product-source]'))}
function localTopicFor(source){const text=source.toLowerCase();if(/qc|photo|inspect|image/.test(text))return'qc';if(/warehouse|repack|consolidat/.test(text))return'warehouse';if(/shipping|ship |route|parcel|weight|dimension|customs/.test(text))return'shipping';if(/return|refund|exchange|eligib/.test(text))return'returns';if(/tracking|track |carrier|dispatch/.test(text))return'tracking';if(/product|link|seller|size|colour|color|listing|source|option/.test(text))return'product';return'general'}
function localTopicText(source,lang,node){
  if(sourceDataNode(node)||!/[A-Za-z]/.test(source))return source;
  const topic=localTopicFor(source);const base=localTopics[lang]?.[topic];if(!base)return source;
  const tag=node?.parentElement?.tagName?.toLowerCase();
  if(['h1','h2','h3','strong','small','span','a','button'].includes(tag)||source.length<90)return localShortTopics[lang]?.[topic]||source;
  const details=localDetailSentences[lang]||[];
  const seed=stableHash(source),parts=base.length<=source.length?[base]:[];let cursor=0;
  // Keep every source paragraph as a full locale paragraph of comparable size.
  // No nodes are added, removed, or merged while switching languages.
  while(cursor<details.length){const next=details[(seed+cursor)%details.length];if(`${parts.join(' ')} ${next}`.trim().length>source.length)break;parts.push(next);cursor++}
  return parts.join(' ')||source;
}
function localizeListingText(source,lang){
  const ui=listingUi[lang];if(!ui)return source;
  const exact={'PIKOBUY CATALOGUE':ui.catalogue,'Browse product categories.':ui.browse,'Choose a category and its matching imported products will appear below on this page.':ui.choose,'Every imported product, in one place.':ui.all,'Showing imported product data and child-site product details.':ui.summary,'No products matched this search. Try a different product name or category.':ui.empty}[source];
  if(exact)return exact;
  let match=source.match(/^(\d+) imported products$/);if(match)return `${match[1]} ${ui.imported}`;
  match=source.match(/^(\d+) products currently imported$/);if(match)return `${match[1]} ${ui.current}`;
  return source;
}
function localizeChecklistText(source,lang){
  const index=checklistSource.indexOf(source),localized=checklistLocales[lang];
  return index>=0&&localized?.[index]?localized[index]:source;
}
const exactGuideParagraphs={"Build a small shortlist, not a very large cart. A deliberate first parcel makes it easier to understand the purchasing payment, the warehouse stage and the later international-shipping payment as separate decisions.":{"de":"Erstelle eine kleine Auswahlliste statt eines sehr großen Warenkorbs. Ein bewusst zusammengestelltes erstes Paket hilft, die Zahlung für den Kauf, die Lagerphase und die spätere Zahlung für den internationalen Versand als getrennte Entscheidungen zu verstehen.","fr":"Préparez une courte sélection plutôt qu’un très grand panier. Un premier colis préparé avec soin aide à distinguer le paiement de l’achat, l’étape de l’entrepôt et le paiement ultérieur du transport international.","es":"Prepara una selección pequeña en lugar de un carrito muy grande. Un primer paquete planificado ayuda a distinguir el pago de la compra, la etapa de almacén y el pago posterior del envío internacional.","it":"Prepara una selezione ridotta invece di un carrello molto grande. Un primo pacco pianificato aiuta a distinguere il pagamento dell’acquisto, la fase in magazzino e il successivo pagamento della spedizione internazionale.","pt":"Prepare uma seleção pequena em vez de um carrinho muito grande. Uma primeira encomenda planeada ajuda a distinguir o pagamento da compra, a fase de armazém e o pagamento posterior do envio internacional.","nl":"Maak een korte selectie in plaats van een zeer groot winkelmandje. Een zorgvuldig samengesteld eerste pakket helpt om de betaling voor de aankoop, de magazijnfase en de latere betaling voor internationale verzending als afzonderlijke beslissingen te zien.","pl":"Przygotuj krótką listę zamiast bardzo dużego koszyka. Starannie zaplanowana pierwsza paczka pomaga oddzielić płatność za zakup, etap magazynowy i późniejszą płatność za wysyłkę międzynarodową.","sv":"Gör en kort lista i stället för en mycket stor varukorg. Ett genomtänkt första paket gör det lättare att skilja betalningen för köpet, lagerfasen och den senare betalningen för internationell frakt åt."},"Keeping product research inside a short, traceable checklist is more valuable than clicking through dozens of links. It gives you a clear record to compare with the later warehouse images.":{"de":"Eine kurze, nachvollziehbare Prüfliste für die Produktrecherche ist hilfreicher als das Durchklicken Dutzender Links. Sie liefert eine klare Grundlage für den späteren Vergleich mit den Lagerfotos.","fr":"Une courte liste de contrôle traçable est plus utile que de parcourir des dizaines de liens. Elle fournit une référence claire à comparer aux futures photos de l’entrepôt.","es":"Una lista de comprobación breve y verificable es más útil que recorrer decenas de enlaces. Te proporciona un registro claro para compararlo después con las fotos del almacén.","it":"Una breve lista di controllo tracciabile è più utile che aprire decine di link. Offre un riferimento chiaro da confrontare con le successive foto del magazzino.","pt":"Uma lista de verificação curta e rastreável é mais útil do que percorrer dezenas de ligações. Fornece um registo claro para comparar mais tarde com as imagens do armazém.","nl":"Een korte, herleidbare checklist voor productonderzoek is nuttiger dan tientallen links openen. Je houdt zo een duidelijk overzicht over om later met de magazijnfoto’s te vergelijken.","pl":"Krótka lista kontrolna z możliwością sprawdzenia źródeł jest bardziej przydatna niż przeglądanie dziesiątek linków. Daje jasny zapis do późniejszego porównania ze zdjęciami magazynowymi.","sv":"En kort och spårbar checklista för produktundersökningen är mer användbar än att klicka igenom mängder av länkar. Den ger ett tydligt underlag att jämföra med lagerbilderna senare."},"These checks are small, but they are the foundation of a better QC comparison later. A warehouse image is only useful if you know exactly which option was intended.":{"de":"Diese kleinen Kontrollen bilden die Grundlage für einen besseren späteren QC-Vergleich. Ein Lagerfoto ist nur hilfreich, wenn du genau weißt, welche Variante bestellt werden sollte.","fr":"Ces vérifications simples facilitent la comparaison QC ultérieure. Une photo d’entrepôt n’est utile que si vous savez exactement quelle variante était prévue.","es":"Estas pequeñas comprobaciones facilitan la comparación QC posterior. Una imagen del almacén solo es útil si sabes exactamente qué opción habías elegido.","it":"Questi piccoli controlli sono la base per un confronto QC migliore. Una foto del magazzino è utile solo se sai esattamente quale variante era prevista.","pt":"Estas pequenas verificações são a base de uma melhor comparação QC. Uma imagem do armazém só é útil se souber exatamente qual era a opção pretendida.","nl":"Deze kleine controles vormen de basis voor een betere QC-vergelijking. Een magazijnfoto is alleen nuttig als je precies weet welke variant bedoeld was.","pl":"Te drobne kontrole są podstawą lepszego późniejszego porównania QC. Zdjęcie magazynowe jest przydatne tylko wtedy, gdy wiadomo dokładnie, jaki wariant wybrano.","sv":"De här små kontrollerna lägger grunden för en bättre QC-jämförelse. En lagerbild är bara användbar om du vet exakt vilken variant som var avsedd."},"Before payment, review the displayed route details, the address, the parcel declaration requirements and the final dimensions. This makes an estimate useful without presenting it as a guaranteed outcome.":{"de":"Prüfe vor der Zahlung die angezeigten Angaben zum Versandweg, die Adresse, die Anforderungen an die Paketanmeldung und die endgültigen Maße. So bleibt die Schätzung eine Planungshilfe und wird nicht als Garantie dargestellt.","fr":"Avant de payer, vérifiez les détails de l’itinéraire affiché, l’adresse, les exigences de déclaration et les dimensions finales. L’estimation reste ainsi une aide à la planification, sans garantie de résultat.","es":"Antes de pagar, revisa los detalles de la ruta, la dirección, los requisitos de declaración y las dimensiones finales. Así la estimación sirve para planificar sin presentarse como una garantía.","it":"Prima di pagare, controlla i dettagli della rotta, l’indirizzo, i requisiti di dichiarazione e le dimensioni finali. La stima resta così uno strumento di pianificazione, non una garanzia.","pt":"Antes de pagar, reveja os detalhes da rota, a morada, os requisitos de declaração e as dimensões finais. Assim, a estimativa serve para planear sem ser apresentada como garantia.","nl":"Controleer vóór betaling de getoonde routegegevens, het adres, de aangiftevereisten en de definitieve afmetingen. Zo blijft de schatting een hulpmiddel voor planning en geen garantie.","pl":"Przed płatnością sprawdź szczegóły trasy, adres, wymagania dotyczące deklaracji i ostateczne wymiary. Dzięki temu wycena pomaga planować, ale nie jest gwarancją wyniku.","sv":"Kontrollera ruttuppgifterna, adressen, deklarationskraven och de slutliga måtten före betalning. Då kan uppskattningen användas för planering utan att ses som en garanti."},"The concise rule is: inspect early, document the issue, check the live eligibility terms and submit a clear request within the stated window when applicable. Do not present a return as guaranteed before those conditions are met.":{"de":"Die Faustregel lautet: früh prüfen, das Problem dokumentieren, die aktuellen Bedingungen lesen und gegebenenfalls innerhalb der genannten Frist einen klaren Antrag stellen. Ein Rückgaberecht ist vor Erfüllung dieser Bedingungen nicht garantiert.","fr":"En pratique : inspectez rapidement, documentez le problème, consultez les conditions en vigueur et présentez une demande claire dans le délai applicable. Un retour n’est pas garanti avant que ces conditions soient remplies.","es":"La regla práctica es inspeccionar pronto, documentar el problema, consultar las condiciones vigentes y presentar una solicitud clara dentro del plazo aplicable. La devolución no está garantizada antes de cumplir esas condiciones.","it":"In pratica: controlla presto, documenta il problema, verifica le condizioni attuali e presenta una richiesta chiara entro il termine applicabile. Il reso non è garantito prima che tali condizioni siano soddisfatte.","pt":"A regra prática é inspecionar cedo, documentar o problema, verificar as condições atuais e apresentar um pedido claro dentro do prazo aplicável. A devolução não é garantida antes de essas condições serem cumpridas.","nl":"Controleer op tijd, leg het probleem vast, lees de actuele voorwaarden en dien waar van toepassing binnen de gestelde termijn een duidelijk verzoek in. Een retour is niet gegarandeerd voordat aan die voorwaarden is voldaan.","pl":"Zasada jest prosta: sprawdź produkt wcześnie, udokumentuj problem, zapoznaj się z aktualnymi warunkami i w odpowiednim terminie złóż jasny wniosek. Zwrot nie jest gwarantowany przed spełnieniem tych warunków.","sv":"Kontrollera tidigt, dokumentera problemet, läs de aktuella villkoren och skicka vid behov en tydlig begäran inom den angivna tiden. En retur är inte garanterad innan villkoren är uppfyllda."},"The warehouse is also the best point to check whether the selected item matches the source record. Keep the original title, product ID and option details visible in the product page so that a photo comparison does not depend on memory alone.":{"de":"Im Lager lässt sich prüfen, ob der gewählte Artikel mit der ursprünglichen Angabe übereinstimmt. Halte Originaltitel, Produkt-ID und Variantendetails auf der Produktseite bereit, damit der Fotovergleich nicht allein vom Gedächtnis abhängt.","fr":"L’étape de l’entrepôt permet aussi de vérifier si l’article choisi correspond à la fiche source. Gardez le titre original, l’identifiant produit et les détails de la variante à portée de main pour comparer les photos sans dépendre uniquement de votre mémoire.","es":"El almacén también es el momento de comprobar si el artículo elegido coincide con la ficha original. Ten a mano el título, el ID y los detalles de la opción para comparar las fotos sin depender solo de la memoria.","it":"La fase in magazzino permette anche di verificare se l’articolo scelto corrisponde alla scheda originale. Tieni a portata di mano titolo, ID e dettagli della variante per confrontare le foto senza affidarti solo alla memoria.","pt":"A etapa de armazém também permite verificar se o artigo escolhido corresponde ao registo original. Tenha à mão o título, o ID e os detalhes da opção para comparar as fotos sem depender apenas da memória.","nl":"In het magazijn kun je ook controleren of het gekozen artikel overeenkomt met de brongegevens. Houd de oorspronkelijke titel, product-ID en optiegegevens bij de hand, zodat je de foto’s niet alleen op basis van je geheugen vergelijkt.","pl":"Etap magazynowy pozwala też sprawdzić, czy wybrany produkt odpowiada zapisowi źródłowemu. Miej pod ręką pierwotny tytuł, ID i szczegóły wariantu, aby nie porównywać zdjęć wyłącznie z pamięci.","sv":"I lagerfasen kan du också kontrollera om den valda varan motsvarar källuppgifterna. Ha ursprunglig titel, produkt-ID och variantuppgifter till hands så att bildjämförelsen inte bara bygger på minnet."},"Finally, keep a record of the product ID, warehouse images, parcel number and route. It makes a future question more precise and helps you distinguish a source-listing issue, warehouse issue and carrier issue without assuming that every problem has the same solution.":{"de":"Bewahre schließlich Produkt-ID, Lagerbilder, Paketnummer und Versandweg auf. Damit kannst du spätere Fragen genauer stellen und Probleme beim Angebot, im Lager und beim Versanddienst unterscheiden, ohne für jedes Problem dieselbe Lösung anzunehmen.","fr":"Conservez enfin l’identifiant du produit, les photos d’entrepôt, le numéro du colis et l’itinéraire. Ces informations facilitent une demande précise et permettent de distinguer un problème de fiche, d’entrepôt ou de transporteur, sans supposer une solution unique.","es":"Por último, guarda el ID del producto, las imágenes del almacén, el número de paquete y la ruta. Esto permite formular consultas precisas y distinguir problemas del anuncio, del almacén o del transportista, sin asumir que todos tienen la misma solución.","it":"Infine conserva ID del prodotto, foto del magazzino, numero del pacco e rotta. Questi dati aiutano a formulare richieste precise e a distinguere problemi della scheda, del magazzino o del corriere, senza presumere un’unica soluzione.","pt":"Por fim, guarde o ID do produto, as imagens do armazém, o número da encomenda e a rota. Estes dados ajudam a fazer perguntas precisas e a distinguir problemas do anúncio, do armazém ou da transportadora, sem presumir uma solução igual para todos.","nl":"Bewaar tot slot de product-ID, magazijnfoto’s, het pakketnummer en de route. Zo kun je later gerichter vragen stellen en problemen met de bronvermelding, het magazijn of de vervoerder onderscheiden zonder één oplossing voor alles aan te nemen.","pl":"Na koniec zachowaj ID produktu, zdjęcia magazynowe, numer paczki i trasę. Ułatwi to precyzyjne pytania oraz rozróżnienie problemu oferty, magazynu lub przewoźnika, bez zakładania jednego rozwiązania dla wszystkich sytuacji.","sv":"Spara slutligen produkt-ID, lagerbilder, paketnummer och rutt. Det gör senare frågor mer precisa och hjälper dig att skilja problem med källannonsen, lagret och transportören åt utan att anta att alla problem har samma lösning."},"Risk-aware content is more useful than absolute claims. It explains what a buyer can verify—product type, route eligibility, address and shipment options—while leaving legal, customs and carrier outcomes to the applicable authorities and providers.":{"de":"Eine realistische Risikoeinschätzung ist hilfreicher als absolute Zusagen. Prüfen lassen sich Warenart, Eignung des Versandwegs, Adresse und Versandoptionen; rechtliche, zollrechtliche und transportbezogene Entscheidungen liegen bei den zuständigen Stellen und Dienstleistern.","fr":"Une évaluation réaliste des risques est plus utile que des promesses absolues. L’acheteur peut vérifier le type de produit, l’admissibilité de l’itinéraire, l’adresse et les options d’envoi ; les décisions juridiques, douanières et du transporteur relèvent des autorités et prestataires concernés.","es":"Una evaluación realista de riesgos es más útil que las promesas absolutas. El comprador puede comprobar el tipo de producto, la elegibilidad de la ruta, la dirección y las opciones de envío; las decisiones legales, aduaneras y del transportista corresponden a las autoridades y proveedores competentes.","it":"Una valutazione realistica dei rischi è più utile di promesse assolute. L’acquirente può verificare tipo di prodotto, idoneità della rotta, indirizzo e opzioni di spedizione; gli esiti legali, doganali e del trasporto dipendono dalle autorità e dai fornitori competenti.","pt":"Uma avaliação realista dos riscos é mais útil do que promessas absolutas. O comprador pode verificar o tipo de produto, a elegibilidade da rota, a morada e as opções de envio; os resultados legais, aduaneiros e da transportadora dependem das autoridades e dos prestadores competentes.","nl":"Een realistische risico-inschatting is nuttiger dan absolute beloften. De koper kan producttype, geschiktheid van de route, adres en verzendopties controleren; juridische, douane- en vervoerdersbeslissingen liggen bij de bevoegde instanties en dienstverleners.","pl":"Realistyczna ocena ryzyka jest bardziej przydatna niż bezwarunkowe obietnice. Kupujący może sprawdzić rodzaj produktu, dostępność trasy, adres i opcje wysyłki; kwestie prawne, celne i transportowe zależą od właściwych organów i dostawców.","sv":"En realistisk riskbedömning är mer användbar än absoluta löften. Köparen kan kontrollera produkttyp, ruttens tillgänglighet, adress och fraktalternativ; juridiska beslut, tullbeslut och transportörens hantering ligger hos ansvariga myndigheter och leverantörer."},"The safer decision is to inspect the visible facts early, while the item is still in the warehouse and before a parcel is submitted. If a difference matters, consult the live policy and seller eligibility rather than assuming any later remedy is automatic.":{"de":"Prüfe sichtbare Details möglichst früh, solange der Artikel im Lager ist und bevor du das Paket abschickst. Wenn eine Abweichung wichtig ist, lies die aktuelle Richtlinie und prüfe die Bedingungen des Verkäufers, statt eine spätere Lösung als selbstverständlich anzunehmen.","fr":"Vérifiez rapidement les éléments visibles, tant que l’article est à l’entrepôt et avant l’envoi du colis. Si une différence est importante, consultez la politique actuelle et les conditions du vendeur sans supposer qu’un recours ultérieur sera automatique.","es":"Revisa pronto los detalles visibles mientras el artículo está en el almacén y antes de enviar el paquete. Si una diferencia es importante, consulta la política vigente y las condiciones del vendedor; no des por hecho que habrá una solución automática después.","it":"Controlla presto gli elementi visibili mentre l’articolo è in magazzino e prima di inviare il pacco. Se una differenza è importante, verifica la politica attuale e le condizioni del venditore senza presumere un rimedio automatico successivo.","pt":"Verifique cedo os detalhes visíveis enquanto o artigo está no armazém e antes de enviar a encomenda. Se uma diferença for importante, consulte a política atual e as condições do vendedor, sem presumir uma solução automática posterior.","nl":"Controleer zichtbare details vroeg, zolang het artikel in het magazijn ligt en voordat het pakket wordt verzonden. Is een afwijking belangrijk, controleer dan het actuele beleid en de voorwaarden van de verkoper; ga niet uit van een automatische oplossing achteraf.","pl":"Sprawdź widoczne szczegóły wcześnie, gdy produkt jest jeszcze w magazynie i przed nadaniem paczki. Jeśli różnica ma znaczenie, sprawdź aktualną politykę i warunki sprzedawcy, nie zakładając automatycznego rozwiązania później.","sv":"Granska synliga detaljer tidigt medan varan finns på lagret och innan paketet skickas. Om en avvikelse är viktig, kontrollera aktuella regler och säljarens villkor i stället för att anta att en lösning senare sker automatiskt."},"For content that ranks responsibly, avoid claiming that a route is always fast or that tracking always updates at a fixed hour. The useful answer is how to read the status, when to check again and when the current official support channel is appropriate.":{"de":"Eine Route ist nicht immer schnell und die Sendungsverfolgung wird nicht garantiert zu einer festen Uhrzeit aktualisiert. Entscheidend ist, den Status zu lesen, später erneut zu prüfen und bei Bedarf den aktuellen offiziellen Support zu kontaktieren.","fr":"Un itinéraire n’est pas toujours rapide et le suivi ne se met pas nécessairement à jour à heure fixe. L’essentiel est de lire le statut, de vérifier à nouveau plus tard et de contacter l’assistance officielle actuelle si nécessaire.","es":"Una ruta no siempre es rápida y el seguimiento no se actualiza necesariamente a una hora fija. Lo útil es leer el estado, volver a comprobarlo más tarde y acudir al soporte oficial vigente cuando sea necesario.","it":"Una rotta non è sempre veloce e il tracciamento non si aggiorna necessariamente a un’ora fissa. È utile leggere lo stato, ricontrollare più tardi e contattare l’assistenza ufficiale attuale quando necessario.","pt":"Uma rota nem sempre é rápida e o rastreio não é necessariamente atualizado a uma hora fixa. O importante é ler o estado, verificar novamente mais tarde e contactar o apoio oficial atual quando necessário.","nl":"Een route is niet altijd snel en tracking wordt niet noodzakelijk op een vast tijdstip bijgewerkt. Lees de status, controleer later opnieuw en neem zo nodig contact op met de actuele officiële ondersteuning.","pl":"Trasa nie zawsze jest szybka, a śledzenie nie musi aktualizować się o stałej godzinie. Warto odczytać status, sprawdzić go ponownie później i w razie potrzeby skontaktować się z aktualnym oficjalnym wsparciem.","sv":"En rutt är inte alltid snabb och spårningen uppdateras inte nödvändigtvis vid en bestämd tid. Läs statusen, kontrollera igen senare och kontakta vid behov den aktuella officiella supporten."},"“PikoBuy QC photos” is a high-intent search because buyers want evidence before they pay international shipping. PikoBuy's public guide says items are checked in at the warehouse, photographed for confirmation and checked for defects. Its shipping terms also say that users can view inspection photos and may purchase additional detailed photos. This is useful evidence, but it has limits.":{"de":"Wer nach „PikoBuy QC photos“ sucht, möchte vor der Zahlung für den internationalen Versand Belege sehen. Laut dem öffentlichen PikoBuy-Leitfaden werden Artikel im Lager eingebucht, zur Bestätigung fotografiert und auf Mängel geprüft. Die Versandbedingungen nennen auch Inspektionsfotos und gegebenenfalls zusätzlich kaufbare Detailfotos. Diese Bilder sind hilfreich, haben aber Grenzen.","fr":"Les personnes recherchant « PikoBuy QC photos » veulent des éléments avant de payer le transport international. Le guide public PikoBuy indique que les articles sont enregistrés à l’entrepôt, photographiés pour confirmation et contrôlés pour détecter des défauts. Les conditions de transport mentionnent aussi les photos d’inspection et la possibilité d’acheter des photos détaillées supplémentaires. Ces images sont utiles, mais limitées.","es":"Quienes buscan «PikoBuy QC photos» quieren pruebas antes de pagar el envío internacional. La guía pública de PikoBuy indica que los artículos se registran en el almacén, se fotografían para su confirmación y se revisan en busca de defectos. Las condiciones de envío también mencionan fotos de inspección y la posibilidad de comprar fotos detalladas adicionales. Son pruebas útiles, pero tienen límites.","it":"Chi cerca «PikoBuy QC photos» vuole elementi di verifica prima di pagare la spedizione internazionale. La guida pubblica PikoBuy indica che gli articoli vengono registrati in magazzino, fotografati per conferma e controllati per eventuali difetti. Le condizioni di spedizione menzionano anche le foto di ispezione e la possibilità di acquistare immagini dettagliate aggiuntive. Sono prove utili, ma hanno limiti.","pt":"Quem pesquisa «PikoBuy QC photos» procura provas antes de pagar o envio internacional. O guia público da PikoBuy indica que os artigos são registados no armazém, fotografados para confirmação e inspecionados quanto a defeitos. As condições de envio também mencionam fotografias de inspeção e a possibilidade de comprar imagens detalhadas adicionais. São provas úteis, mas têm limites.","nl":"Wie zoekt naar “PikoBuy QC photos” wil bewijs zien voordat internationale verzending wordt betaald. Volgens de openbare PikoBuy-gids worden artikelen in het magazijn geregistreerd, voor bevestiging gefotografeerd en op gebreken gecontroleerd. De verzendvoorwaarden noemen ook inspectiefoto’s en eventueel aan te schaffen extra detailfoto’s. Die beelden zijn nuttig, maar hebben beperkingen.","pl":"Osoby szukające „PikoBuy QC photos” chcą zobaczyć materiał przed opłaceniem wysyłki międzynarodowej. Publiczny poradnik PikoBuy podaje, że produkty są przyjmowane w magazynie, fotografowane w celu potwierdzenia i sprawdzane pod kątem wad. Warunki wysyłki mówią także o zdjęciach kontrolnych i możliwości zakupu dodatkowych zdjęć szczegółowych. To przydatny materiał, ale ma ograniczenia.","sv":"Den som söker efter ”PikoBuy QC photos” vill se underlag innan den internationella frakten betalas. Enligt PikoBuys offentliga guide registreras varorna på lagret, fotograferas för bekräftelse och kontrolleras för defekter. Fraktvillkoren nämner även inspektionsbilder och möjligheten att köpa extra detaljbilder. Bilderna är användbara men har begränsningar."},"Use QC photos to compare observable details: the selected colour, the overall shape, obvious stains or damage, simple label placement, packaging condition and included accessories. Put the source image and warehouse image side by side, then ask a focused question when there is a mismatch. A focused request such as “please show the left side panel” is more useful than a general request for “better QC.”":{"de":"Vergleiche auf QC-Fotos sichtbare Details: gewählte Farbe, Gesamtform, offensichtliche Flecken oder Schäden, Position von Etiketten, Verpackungszustand und enthaltenes Zubehör. Lege Quellbild und Lagerfoto nebeneinander und stelle bei Abweichungen eine konkrete Frage. „Bitte die linke Seitenfläche zeigen“ ist hilfreicher als eine allgemeine Bitte um „bessere QC“.","fr":"Comparez les détails visibles sur les photos QC : couleur choisie, forme générale, taches ou dégâts évidents, position des étiquettes, état de l’emballage et accessoires inclus. Placez l’image source et la photo d’entrepôt côte à côte et posez une question précise en cas de différence. Demander « montrez le panneau gauche » est plus utile qu’une demande générale de « meilleure QC ».","es":"Compara en las fotos QC los detalles visibles: color elegido, forma general, manchas o daños evidentes, ubicación de etiquetas, estado del embalaje y accesorios incluidos. Pon la imagen original y la del almacén una junto a otra y haz una pregunta concreta si no coinciden. Pedir «muestra el panel lateral izquierdo» es más útil que solicitar una «mejor QC» en general.","it":"Confronta nelle foto QC i dettagli visibili: colore scelto, forma generale, macchie o danni evidenti, posizione delle etichette, stato dell’imballaggio e accessori inclusi. Metti l’immagine originale accanto a quella del magazzino e poni una domanda precisa in caso di differenze. Chiedere «mostrate il pannello laterale sinistro» è più utile di una richiesta generica di «QC migliore».","pt":"Compare nas fotos QC os detalhes visíveis: cor escolhida, forma geral, manchas ou danos evidentes, posição das etiquetas, estado da embalagem e acessórios incluídos. Coloque a imagem de origem ao lado da imagem do armazém e faça uma pergunta específica se houver diferenças. Pedir «mostrem o painel lateral esquerdo» é mais útil do que solicitar uma «QC melhor» de forma genérica.","nl":"Vergelijk op QC-foto’s zichtbare details: de gekozen kleur, algemene vorm, duidelijke vlekken of schade, plaatsing van labels, staat van de verpakking en meegeleverde accessoires. Leg de bronafbeelding naast de magazijnfoto en stel bij een verschil een gerichte vraag. “Toon het linker zijpaneel” is nuttiger dan algemeen om “betere QC” vragen.","pl":"Porównaj na zdjęciach QC widoczne szczegóły: wybrany kolor, ogólny kształt, oczywiste plamy lub uszkodzenia, położenie metek, stan opakowania i dołączone akcesoria. Zestaw zdjęcie źródłowe z magazynowym i przy różnicy zadaj konkretne pytanie. Prośba „pokaż lewy panel boczny” jest bardziej pomocna niż ogólne życzenie „lepszej kontroli QC”.","sv":"Jämför synliga detaljer på QC-bilderna: vald färg, övergripande form, tydliga fläckar eller skador, etikettplacering, förpackningens skick och medföljande tillbehör. Lägg källbilden bredvid lagerbilden och ställ en tydlig fråga om något skiljer sig. ”Visa den vänstra sidopanelen” är mer användbart än en allmän begäran om ”bättre QC”."},"QC photos are not authentication certificates, material tests, professional measurements or a guarantee that an item will perform as expected. PikoBuy's published terms state that professional inspection may not be available for certain products, and sealed packaging may not be opened for inspection. That is especially important for electronics, fragile goods and products where the relevant feature is not visible in a normal warehouse photograph.":{"de":"QC-Fotos sind weder Echtheitszertifikate noch Materialtests, professionelle Messungen oder eine Leistungsgarantie. Laut den veröffentlichten PikoBuy-Bedingungen ist eine professionelle Prüfung für manche Produkte möglicherweise nicht verfügbar; versiegelte Verpackungen werden zur Prüfung möglicherweise nicht geöffnet. Das ist besonders bei Elektronik, zerbrechlichen Waren und Merkmalen wichtig, die auf normalen Lagerfotos nicht sichtbar sind.","fr":"Les photos QC ne sont ni des certificats d’authenticité, ni des tests de matériaux, ni des mesures professionnelles, et ne garantissent pas le fonctionnement attendu. Les conditions publiées par PikoBuy précisent qu’une inspection professionnelle peut ne pas être disponible pour certains produits et qu’un emballage scellé peut ne pas être ouvert. Cela compte particulièrement pour l’électronique, les objets fragiles et les caractéristiques invisibles sur une photo d’entrepôt ordinaire.","es":"Las fotos QC no son certificados de autenticidad, pruebas de materiales, mediciones profesionales ni una garantía de funcionamiento. Las condiciones publicadas de PikoBuy indican que puede no haber inspección profesional para ciertos productos y que los embalajes sellados pueden no abrirse para revisarlos. Esto importa especialmente para aparatos electrónicos, artículos frágiles y características que no se ven en una foto normal del almacén.","it":"Le foto QC non sono certificati di autenticità, test dei materiali, misurazioni professionali o garanzie di funzionamento. Le condizioni pubblicate da PikoBuy indicano che il controllo professionale potrebbe non essere disponibile per alcuni prodotti e che le confezioni sigillate potrebbero non essere aperte. Questo conta soprattutto per elettronica, articoli fragili e caratteristiche non visibili in una normale foto di magazzino.","pt":"As fotos QC não são certificados de autenticidade, testes de materiais, medições profissionais nem garantia de funcionamento. As condições publicadas da PikoBuy indicam que a inspeção profissional pode não estar disponível para certos produtos e que embalagens seladas podem não ser abertas para inspeção. Isto é particularmente relevante para eletrónica, artigos frágeis e características que não aparecem numa fotografia normal de armazém.","nl":"QC-foto’s zijn geen echtheidscertificaten, materiaaltests, professionele metingen of garantie op de werking. Volgens de gepubliceerde PikoBuy-voorwaarden is professionele inspectie mogelijk niet voor alle producten beschikbaar en wordt verzegelde verpakking mogelijk niet geopend. Dit is vooral belangrijk bij elektronica, kwetsbare goederen en eigenschappen die op een gewone magazijnfoto niet zichtbaar zijn.","pl":"Zdjęcia QC nie są certyfikatami autentyczności, testami materiałów, profesjonalnymi pomiarami ani gwarancją działania. Opublikowane warunki PikoBuy wskazują, że profesjonalna kontrola może nie być dostępna dla niektórych produktów, a zapieczętowane opakowanie może nie zostać otwarte. Ma to szczególne znaczenie przy elektronice, delikatnych towarach i cechach niewidocznych na zwykłym zdjęciu magazynowym.","sv":"QC-bilder är inte äkthetsintyg, materialtester, professionella mätningar eller garantier för funktion. PikoBuys publicerade villkor anger att professionell kontroll kanske inte finns för vissa produkter och att förseglade förpackningar kanske inte öppnas. Det är särskilt viktigt för elektronik, ömtåliga varor och egenskaper som inte syns på ett vanligt lagerfoto."},"PikoBuy is positioned as a purchasing and forwarding platform. Its public shopping guide describes a familiar flow: choose an item on a source marketplace, paste a product link or search term into PikoBuy, select the colour, size and quantity, and pay the purchasing order. When the item reaches the warehouse, the next decision is whether to submit it as a parcel using an available international route.":{"de":"PikoBuy ist eine Einkaufs- und Weiterleitungsplattform. Der öffentliche Leitfaden beschreibt den Ablauf: Artikel auf einem Marktplatz auswählen, Link oder Suchbegriff bei PikoBuy eingeben, Farbe, Größe und Menge wählen und die Bestellung bezahlen. Nach Ankunft im Lager entscheidest du, ob der Artikel über einen verfügbaren internationalen Versandweg als Paket verschickt wird.","fr":"PikoBuy est une plateforme d’achat et de réexpédition. Son guide public décrit les étapes : choisir un article sur une place de marché, saisir son lien ou une recherche sur PikoBuy, sélectionner couleur, taille et quantité, puis payer la commande. Une fois l’article à l’entrepôt, vous décidez de l’envoyer ou non par une ligne internationale disponible.","es":"PikoBuy es una plataforma de compra y reenvío. Su guía pública describe el proceso: elegir un artículo en un mercado, introducir su enlace o una búsqueda en PikoBuy, seleccionar color, talla y cantidad y pagar el pedido. Al llegar al almacén, decides si enviarlo como paquete por una ruta internacional disponible.","it":"PikoBuy è una piattaforma di acquisto e inoltro. La guida pubblica descrive il percorso: scegliere un articolo su un marketplace, inserire link o ricerca su PikoBuy, selezionare colore, taglia e quantità e pagare l’ordine. All’arrivo in magazzino decidi se spedirlo in un pacco tramite una rotta internazionale disponibile.","pt":"A PikoBuy é uma plataforma de compra e reencaminhamento. O guia público descreve o processo: escolher um artigo num mercado, inserir a ligação ou pesquisa na PikoBuy, selecionar cor, tamanho e quantidade e pagar a compra. Quando chega ao armazém, decide se o envia numa encomenda por uma rota internacional disponível.","nl":"PikoBuy is een aankoop- en doorstuurplatform. De openbare gids beschrijft de stappen: kies een artikel op een marktplaats, voer de productlink of zoekterm bij PikoBuy in, selecteer kleur, maat en aantal en betaal de bestelling. Na aankomst in het magazijn beslis je of je het artikel via een beschikbare internationale route als pakket verstuurt.","pl":"PikoBuy to platforma zakupowa i pośrednicząca w wysyłce. Publiczny poradnik opisuje kolejne kroki: wybierz produkt na platformie sprzedażowej, wklej link lub wpisz wyszukiwaną frazę w PikoBuy, wybierz kolor, rozmiar i ilość, a następnie opłać zamówienie. Po dostarczeniu do magazynu decydujesz, czy wysłać produkt dostępną trasą międzynarodową.","sv":"PikoBuy är en plattform för inköp och vidarebefordran. Den offentliga guiden beskriver stegen: välj en vara på en marknadsplats, ange produktlänk eller sökord hos PikoBuy, välj färg, storlek och antal och betala beställningen. När varan kommer till lagret väljer du om den ska skickas som paket via en tillgänglig internationell rutt."},"That sequence is why the most useful research happens before the first payment. Save the item title, selected variation, visible measurements and source photographs. A link alone is not enough when a seller has several versions, colours or size charts. The warehouse process can confirm that an item has arrived and provide inspection photos, but it cannot turn an unclear order into the right variant after the fact.":{"de":"Deshalb ist die Recherche vor der ersten Zahlung besonders wichtig. Speichere Produkttitel, gewählte Variante, sichtbare Maße und Quellfotos. Ein Link allein genügt bei mehreren Versionen, Farben oder Größentabellen nicht. Das Lager kann den Eingang bestätigen und Prüffotos bereitstellen, aber eine unklare Bestellung nicht nachträglich in die richtige Variante verwandeln.","fr":"Les recherches sont donc particulièrement utiles avant le premier paiement. Enregistrez le titre, la variante choisie, les mesures visibles et les photos source. Un lien seul ne suffit pas si le vendeur propose plusieurs versions, couleurs ou tableaux de tailles. L’entrepôt peut confirmer l’arrivée et fournir des photos de contrôle, mais ne peut pas corriger après coup une commande imprécise.","es":"Por eso conviene investigar antes del primer pago. Guarda el título, la variante seleccionada, las medidas visibles y las fotos originales. Un enlace no basta si el vendedor ofrece varias versiones, colores o tablas de tallas. El almacén puede confirmar la llegada y aportar fotos de inspección, pero no convertir después un pedido ambiguo en la variante correcta.","it":"Per questo la ricerca prima del primo pagamento è importante. Salva titolo, variante scelta, misure visibili e foto originali. Un link non basta se il venditore offre più versioni, colori o tabelle taglie. Il magazzino può confermare l’arrivo e fornire foto di controllo, ma non può trasformare dopo un ordine poco chiaro nella variante corretta.","pt":"Por isso, é importante pesquisar antes do primeiro pagamento. Guarde título, variante escolhida, medidas visíveis e fotografias de origem. Uma ligação não basta se o vendedor tiver várias versões, cores ou tabelas de tamanhos. O armazém pode confirmar a chegada e fornecer fotos de inspeção, mas não corrigir posteriormente uma encomenda pouco clara.","nl":"Daarom is onderzoek vóór de eerste betaling belangrijk. Bewaar de titel, gekozen variant, zichtbare afmetingen en bronfoto’s. Een link alleen volstaat niet bij meerdere versies, kleuren of maattabellen. Het magazijn kan de ontvangst bevestigen en inspectiefoto’s leveren, maar kan een onduidelijke bestelling niet achteraf in de juiste variant veranderen.","pl":"Dlatego warto sprawdzić szczegóły przed pierwszą płatnością. Zapisz tytuł, wybrany wariant, widoczne wymiary i zdjęcia źródłowe. Sam link nie wystarczy, gdy sprzedawca oferuje kilka wersji, kolorów lub tabel rozmiarów. Magazyn może potwierdzić przyjęcie i dostarczyć zdjęcia kontrolne, ale nie zamieni później niejasnego zamówienia we właściwy wariant.","sv":"Därför är efterforskningen före första betalningen viktig. Spara titel, vald variant, synliga mått och källbilder. En länk räcker inte om säljaren har flera versioner, färger eller storlekstabeller. Lagret kan bekräfta ankomsten och ge inspektionsbilder, men kan inte i efterhand göra en otydlig beställning till rätt variant."},"For a spreadsheet user, the practical role of a product list is discovery rather than certainty. Treat a product ID, price snapshot and image set as a starting point. Re-open the current listing, compare the selected option, then use the agent route only when the information still matches. PikoBuy's terms also make clear that cross-border charges, route availability and final logistics conditions can vary, so no guide should promise a fixed total or delivery date.":{"de":"Eine Produktliste dient der Suche und bietet keine Gewissheit. Produkt-ID, gespeicherter Preis und Bilder sind nur ein Ausgangspunkt. Öffne das aktuelle Angebot erneut, vergleiche die gewählte Variante und nutze den Agenten erst, wenn alles noch übereinstimmt. Grenzüberschreitende Kosten, Versandwege und Logistikbedingungen können variieren; eine feste Gesamtsumme oder Lieferzeit ist nicht garantiert.","fr":"Une liste de produits sert à la découverte et ne constitue pas une garantie. Identifiant, prix relevé et images sont un point de départ. Rouvrez l’annonce actuelle, comparez la variante choisie et ne poursuivez que si les informations correspondent toujours. Les frais transfrontaliers, lignes disponibles et conditions logistiques peuvent varier : aucun total ni délai fixe n’est garanti.","es":"Una lista de productos sirve para descubrir opciones y no aporta certeza. El ID, el precio registrado y las imágenes son un punto de partida. Abre de nuevo el anuncio actual, compara la opción elegida y continúa solo si los datos aún coinciden. Los cargos internacionales, las rutas y las condiciones logísticas pueden variar, por lo que no se garantiza un total ni una fecha fija.","it":"Un elenco di prodotti serve alla ricerca e non offre certezze. ID, prezzo rilevato e immagini sono un punto di partenza. Riapri l’inserzione attuale, confronta la variante scelta e procedi solo se le informazioni coincidono ancora. Costi transfrontalieri, rotte e condizioni logistiche possono variare: non sono garantiti un totale o una data fissi.","pt":"Uma lista de produtos serve para descobrir opções e não garante certezas. ID, preço registado e imagens são um ponto de partida. Reabra o anúncio atual, compare a opção escolhida e avance apenas se os dados ainda coincidirem. Encargos internacionais, rotas e condições logísticas podem variar, pelo que não há garantia de valor total ou data fixa.","nl":"Een productlijst helpt bij het ontdekken en geeft geen zekerheid. Product-ID, prijsopname en afbeeldingen zijn een vertrekpunt. Open de actuele advertentie opnieuw, vergelijk de gekozen optie en ga alleen verder als de gegevens nog overeenkomen. Internationale kosten, routes en logistieke voorwaarden kunnen veranderen; een vast totaal of vaste leverdatum is niet gegarandeerd.","pl":"Lista produktów służy do wyszukiwania i nie daje pewności. ID, zapis ceny i zdjęcia to punkt wyjścia. Otwórz aktualną ofertę, porównaj wybrany wariant i kontynuuj tylko wtedy, gdy dane nadal się zgadzają. Opłaty międzynarodowe, dostępność tras i warunki logistyczne mogą się zmieniać, więc stała suma ani data dostawy nie są gwarantowane.","sv":"En produktlista hjälper dig att hitta varor men ger ingen säkerhet. Produkt-ID, sparat pris och bilder är en utgångspunkt. Öppna den aktuella annonsen igen, jämför vald variant och gå vidare bara om uppgifterna fortfarande stämmer. Internationella avgifter, tillgängliga rutter och logistikvillkor kan variera; en fast totalsumma eller leveransdag garanteras inte."},"Searches for “PikoBuy shipping cost” often seek a single number, but the official shipping-estimate page asks for a destination, item weight and dimensions. That structure is important: a route can bill by actual weight, volumetric weight or its own rule, while the parcel dimensions can change after items are packed. An estimate is therefore a planning tool, not a promise.":{"de":"Wer nach „PikoBuy shipping cost“ sucht, möchte oft einen festen Betrag. Die offizielle Versandschätzung fragt jedoch nach Zielort, Gewicht und Maßen. Ein Versandweg kann nach tatsächlichem Gewicht, Volumengewicht oder eigenen Regeln abrechnen; zudem können sich die Maße beim Verpacken ändern. Die Schätzung ist daher eine Planungshilfe und keine Zusage.","fr":"La recherche « PikoBuy shipping cost » vise souvent un montant unique, mais l’estimateur officiel demande la destination, le poids et les dimensions. Une ligne peut facturer selon le poids réel, le poids volumétrique ou ses propres règles ; les dimensions peuvent changer après emballage. L’estimation aide donc à planifier sans constituer une promesse.","es":"La búsqueda «PikoBuy shipping cost» suele buscar una cifra única, pero el estimador oficial pide destino, peso y dimensiones. Una ruta puede cobrar según el peso real, el volumétrico o sus propias reglas; las dimensiones pueden cambiar al embalar. Por tanto, la estimación sirve para planificar, no es una promesa.","it":"Chi cerca «PikoBuy shipping cost» desidera spesso una cifra unica, ma lo strumento ufficiale richiede destinazione, peso e dimensioni. Una rotta può addebitare in base al peso effettivo, volumetrico o a proprie regole; le dimensioni possono cambiare con l’imballaggio. La stima serve quindi a pianificare e non è una promessa.","pt":"Quem procura «PikoBuy shipping cost» quer muitas vezes um valor único, mas o estimador oficial pede destino, peso e dimensões. Uma rota pode cobrar pelo peso real, volumétrico ou pelas suas próprias regras; as dimensões podem mudar após a embalagem. A estimativa ajuda a planear, não é uma promessa.","nl":"Wie zoekt naar “PikoBuy shipping cost” wil vaak één bedrag, maar de officiële schatter vraagt bestemming, gewicht en afmetingen. Een route kan rekenen met werkelijk gewicht, volumegewicht of eigen regels; de afmetingen kunnen na het inpakken veranderen. Een schatting helpt daarom bij de planning en is geen belofte.","pl":"Osoby szukające „PikoBuy shipping cost” często oczekują jednej kwoty, ale oficjalny kalkulator wymaga kraju docelowego, wagi i wymiarów. Trasa może rozliczać wagę rzeczywistą, gabarytową lub stosować własne zasady, a wymiary mogą zmienić się po zapakowaniu. Wycena pomaga planować, lecz nie jest obietnicą.","sv":"Den som söker ”PikoBuy shipping cost” vill ofta ha ett enda belopp, men den officiella uppskattningen kräver destination, vikt och mått. En rutt kan debitera efter faktisk vikt, volymvikt eller egna regler, och måtten kan ändras efter packning. Uppskattningen är därför ett planeringsverktyg, inte ett löfte."},"Start with the delivery country and choose only routes that are actually shown for that destination. Then look at the parcel's expected shape as well as its raw item weight. Bulky shoes, outerwear, boxes and fragile packing can affect dimensions more than a quick item-price comparison suggests. Consolidating items may reduce duplicated packing, but it can also create a larger parcel and a different billable profile.":{"de":"Beginne mit dem Zielland und wähle nur dort tatsächlich angebotene Versandwege. Berücksichtige neben dem Artikelgewicht auch die erwartete Paketform. Große Schuhe, Oberbekleidung, Kartons und Schutzverpackungen können die Maße stark beeinflussen. Das Zusammenlegen kann doppelte Verpackung reduzieren, aber auch ein größeres Paket und andere Abrechnungswerte ergeben.","fr":"Commencez par le pays de destination et choisissez uniquement les lignes proposées pour celui-ci. Examinez aussi la forme prévue du colis, pas seulement le poids des articles. Chaussures volumineuses, manteaux, boîtes et protections peuvent modifier les dimensions. Regrouper les articles peut réduire les emballages répétés, mais aussi créer un colis plus grand avec un poids facturable différent.","es":"Empieza por el país de destino y elige solo rutas disponibles para él. Considera también la forma prevista del paquete, no solo el peso de los artículos. Calzado voluminoso, abrigos, cajas y embalaje protector pueden alterar las dimensiones. Consolidar puede reducir embalajes duplicados, pero también crear un paquete mayor con otro peso facturable.","it":"Parti dal paese di destinazione e scegli solo rotte effettivamente disponibili. Considera anche la forma prevista del pacco, oltre al peso degli articoli. Scarpe voluminose, capispalla, scatole e protezioni possono cambiare le dimensioni. Consolidare può ridurre imballaggi duplicati, ma anche creare un pacco più grande con un peso fatturabile diverso.","pt":"Comece pelo país de destino e escolha apenas rotas disponíveis para esse destino. Considere também a forma prevista da encomenda, além do peso dos artigos. Calçado volumoso, casacos, caixas e proteção podem alterar as dimensões. Consolidar pode reduzir embalagens duplicadas, mas também criar um pacote maior com peso faturável diferente.","nl":"Begin met het bestemmingsland en kies alleen routes die daarvoor werkelijk beschikbaar zijn. Kijk naast het artikelgewicht ook naar de verwachte pakketvorm. Grote schoenen, jassen, dozen en beschermend verpakkingsmateriaal kunnen de afmetingen sterk beïnvloeden. Samenvoegen kan dubbele verpakking verminderen, maar ook een groter pakket met ander factureerbaar gewicht opleveren.","pl":"Zacznij od kraju docelowego i wybieraj tylko faktycznie dostępne trasy. Oprócz wagi produktów uwzględnij przewidywany kształt paczki. Duże buty, odzież wierzchnia, pudełka i zabezpieczenia mogą znacząco zmienić wymiary. Łączenie może ograniczyć powtarzające się opakowania, ale też stworzyć większą paczkę z inną wagą rozliczeniową.","sv":"Börja med destinationslandet och välj bara rutter som faktiskt erbjuds dit. Bedöm även paketets förväntade form, inte bara varornas vikt. Skrymmande skor, ytterkläder, lådor och skydd kan påverka måtten. Sammanläggning kan minska dubbla förpackningar men också ge ett större paket med en annan debiterbar vikt."},"Separate product cost from international-shipping cost. The initial purchasing order and the parcel-shipping payment are different stages in PikoBuy's public guide. Taxes, duties, brokerage charges and delivery restrictions can also depend on the destination and route. These variables make broad claims such as “cheapest PikoBuy shipping” unreliable without a real destination, parcel profile and current calculator result.":{"de":"Trenne Produktpreis und internationale Versandkosten. Laut PikoBuy sind die erste Kaufzahlung und die spätere Paketzahlung getrennte Schritte. Steuern, Zölle, Abfertigungsgebühren und Lieferbeschränkungen hängen ebenfalls von Zielort und Route ab. Ohne konkretes Ziel, Paketprofil und aktuelle Berechnung ist die Behauptung „günstigster Versand“ unzuverlässig.","fr":"Séparez le prix du produit des frais internationaux. Le guide PikoBuy distingue le paiement initial de l’achat du paiement ultérieur du colis. Taxes, droits, frais de dédouanement et restrictions peuvent dépendre du pays et de la ligne. Sans destination, caractéristiques du colis et estimation actuelle, une affirmation comme « livraison la moins chère » manque de fiabilité.","es":"Separa el precio del producto del envío internacional. La guía de PikoBuy distingue el pago inicial de la compra del pago posterior del paquete. Impuestos, aranceles, gastos de gestión y restricciones también dependen del destino y la ruta. Sin destino, datos del paquete y cálculo actualizado, afirmar que un envío es «el más barato» no es fiable.","it":"Separa il prezzo del prodotto dalla spedizione internazionale. La guida PikoBuy distingue il pagamento iniziale dell’acquisto da quello successivo del pacco. Imposte, dazi, spese di sdoganamento e restrizioni dipendono anche da destinazione e rotta. Senza destinazione, dati del pacco e preventivo aggiornato, affermare che una spedizione è «la più economica» non è affidabile.","pt":"Separe o preço do produto do envio internacional. O guia da PikoBuy distingue o pagamento inicial da compra do pagamento posterior da encomenda. Impostos, direitos, taxas de desalfandegamento e restrições também dependem do destino e da rota. Sem destino, características da encomenda e cálculo atual, afirmar que um envio é «o mais barato» não é fiável.","nl":"Scheid de productprijs van internationale verzendkosten. De PikoBuy-gids onderscheidt de eerste betaling voor het artikel van de latere betaling voor het pakket. Belastingen, invoerrechten, inklaringskosten en beperkingen hangen ook af van bestemming en route. Zonder bestemming, pakketgegevens en actuele berekening is een claim als “goedkoopste verzending” niet betrouwbaar.","pl":"Oddziel cenę produktu od kosztu wysyłki międzynarodowej. Poradnik PikoBuy rozróżnia pierwszą płatność za zakup i późniejszą płatność za paczkę. Podatki, cła, opłaty za odprawę i ograniczenia dostawy zależą także od kraju i trasy. Bez celu, danych paczki i aktualnej wyceny twierdzenie o „najtańszej wysyłce” jest niewiarygodne.","sv":"Skilj produktpriset från den internationella frakten. PikoBuys guide skiljer den första betalningen för köpet från den senare betalningen för paketet. Skatter, tull, hanteringsavgifter och begränsningar kan också bero på destination och rutt. Utan destination, paketuppgifter och aktuell beräkning är påståenden om ”billigaste frakten” opålitliga."},"Once an item reaches the warehouse, it becomes possible to see it in the account alongside other orders. PikoBuy's guide describes warehouse inspection before the international-shipping stage, while its contact page describes combining items from different sellers into one parcel. This is where product research becomes parcel planning.":{"de":"Nach der Ankunft im Lager ist der Artikel neben anderen Bestellungen im Konto sichtbar. PikoBuys Leitfaden beschreibt die Lagerprüfung vor dem internationalen Versand; die Kontaktseite beschreibt das Zusammenlegen von Artikeln verschiedener Verkäufer in einem Paket. Hier wird aus Produktrecherche die Paketplanung.","fr":"À son arrivée à l’entrepôt, l’article apparaît dans le compte avec les autres commandes. Le guide PikoBuy décrit le contrôle avant l’expédition internationale ; sa page de contact explique le regroupement d’articles de plusieurs vendeurs dans un colis. La recherche produit devient alors une préparation de colis.","es":"Cuando un artículo llega al almacén, puede verse en la cuenta junto con otros pedidos. La guía de PikoBuy describe la inspección antes del envío internacional y su página de contacto explica cómo combinar artículos de varios vendedores en un paquete. En esta etapa la búsqueda se convierte en planificación del paquete.","it":"Quando un articolo arriva in magazzino, appare nell’account insieme agli altri ordini. La guida PikoBuy descrive il controllo prima della spedizione internazionale; la pagina contatti spiega come riunire articoli di più venditori in un pacco. Qui la ricerca diventa pianificazione della spedizione.","pt":"Quando um artigo chega ao armazém, pode ser visto na conta juntamente com outras encomendas. O guia da PikoBuy descreve a inspeção antes do envio internacional; a página de contacto explica a combinação de artigos de vários vendedores num pacote. Nesta fase, a pesquisa passa a ser planeamento da encomenda.","nl":"Zodra een artikel het magazijn bereikt, is het naast andere bestellingen in het account te zien. De PikoBuy-gids beschrijft inspectie vóór internationale verzending; de contactpagina beschrijft het samenvoegen van artikelen van verschillende verkopers in één pakket. Hier wordt productonderzoek pakketplanning.","pl":"Po dotarciu do magazynu produkt można zobaczyć na koncie obok innych zamówień. Poradnik PikoBuy opisuje kontrolę przed wysyłką międzynarodową, a strona kontaktowa wyjaśnia łączenie produktów od różnych sprzedawców w jedną paczkę. Na tym etapie wyszukiwanie przechodzi w planowanie paczki.","sv":"När en vara anländer till lagret kan den ses på kontot tillsammans med andra beställningar. PikoBuys guide beskriver lagerkontroll före internationell frakt, och kontaktsidan beskriver hur varor från olika säljare kan slås ihop i ett paket. Här övergår produktundersökning till paketplanering."},"Consolidation can be sensible when several items are ready and their combined shape still fits a suitable route. It is not automatically cheaper. Combining orders can change the parcel's dimensions, billable weight and available shipping methods. A buyer should compare the actual calculator result after the warehouse has recorded the items, not rely on an early estimate based only on seller weights.":{"de":"Das Zusammenlegen kann sinnvoll sein, wenn mehrere Artikel bereitliegen und ihre gemeinsame Form zu einem geeigneten Versandweg passt. Es ist nicht automatisch billiger: Maße, Abrechnungsgewicht und verfügbare Versandarten können sich ändern. Vergleiche das tatsächliche Rechnerergebnis nach der Lagererfassung, statt nur eine frühe Schätzung anhand der Verkäufergewichte zu verwenden.","fr":"Le regroupement peut convenir lorsque plusieurs articles sont prêts et que leur forme combinée reste compatible avec une ligne adaptée. Il n’est pas automatiquement moins cher : dimensions, poids facturable et modes disponibles peuvent changer. Comparez le résultat réel du calculateur après enregistrement à l’entrepôt, plutôt qu’une estimation initiale fondée sur les seuls poids vendeurs.","es":"Consolidar puede ser útil cuando varios artículos están listos y su forma combinada encaja en una ruta adecuada. No es automáticamente más barato: pueden cambiar dimensiones, peso facturable y métodos disponibles. Compara el resultado real del calculador tras el registro en almacén, no una estimación inicial basada solo en pesos del vendedor.","it":"Il consolidamento può essere utile quando più articoli sono pronti e la loro forma complessiva è adatta a una rotta disponibile. Non è automaticamente più economico: dimensioni, peso fatturabile e metodi possono cambiare. Confronta il risultato effettivo del calcolatore dopo la registrazione in magazzino, non una stima iniziale basata solo sui pesi del venditore.","pt":"A consolidação pode ser útil quando vários artigos estão prontos e a forma combinada cabe numa rota adequada. Não é automaticamente mais barata: dimensões, peso faturável e métodos disponíveis podem mudar. Compare o resultado real do calculador após o registo no armazém, em vez de uma estimativa inicial baseada apenas nos pesos do vendedor.","nl":"Samenvoegen kan zinvol zijn als meerdere artikelen klaarstaan en hun gecombineerde vorm bij een geschikte route past. Het is niet automatisch goedkoper: afmetingen, factureerbaar gewicht en verzendmethoden kunnen veranderen. Vergelijk de werkelijke berekening na magazijnregistratie en vertrouw niet alleen op een vroege schatting met verkopersgewichten.","pl":"Łączenie może mieć sens, gdy kilka produktów jest gotowych, a ich wspólny kształt pasuje do odpowiedniej trasy. Nie jest automatycznie tańsze: mogą zmienić się wymiary, waga rozliczeniowa i dostępne metody. Porównaj wynik kalkulatora po zarejestrowaniu towarów w magazynie, zamiast polegać wyłącznie na wczesnej wycenie z wag sprzedawców.","sv":"Sammanslagning kan vara rimlig när flera varor är klara och deras gemensamma form passar en lämplig rutt. Det är inte automatiskt billigare: mått, debiterbar vikt och tillgängliga fraktsätt kan ändras. Jämför kalkylatorns faktiska resultat efter lagerregistreringen i stället för en tidig uppskattning enbart utifrån säljarvikter."},"Repacking requests should be specific. Examples include reducing unnecessary packaging, reinforcing a fragile outer box or using a smaller packing method where available. Do not assume every request can be fulfilled, and do not ask warehouse staff to override route restrictions or customs rules. If an item is sensitive, fragile or has batteries, liquids or unusual dimensions, read the current route conditions before adding it to a parcel.":{"de":"Formuliere Umpackwünsche konkret, etwa weniger unnötige Verpackung, einen verstärkten Karton für Zerbrechliches oder eine kleinere Verpackung, falls verfügbar. Nicht jeder Wunsch ist erfüllbar; das Lager soll weder Versandbeschränkungen noch Zollregeln umgehen. Prüfe bei empfindlichen oder zerbrechlichen Waren, Batterien, Flüssigkeiten und ungewöhnlichen Maßen die aktuellen Routenbedingungen vor dem Einpacken.","fr":"Formulez précisément les demandes de réemballage : réduire les emballages inutiles, renforcer une boîte fragile ou choisir un emballage plus petit si disponible. Toute demande n’est pas forcément réalisable ; ne demandez pas de contourner les restrictions ou règles douanières. Pour les objets sensibles ou fragiles, batteries, liquides ou dimensions inhabituelles, vérifiez les conditions actuelles avant regroupement.","es":"Formula solicitudes de reembalaje concretas: reducir embalaje innecesario, reforzar una caja frágil o usar un formato menor si existe. No todas podrán cumplirse; no pidas al almacén ignorar restricciones ni normas aduaneras. Para artículos sensibles o frágiles, baterías, líquidos o dimensiones inusuales, consulta las condiciones actuales antes de añadirlos al paquete.","it":"Formula richieste di reimballaggio precise: ridurre l’imballaggio inutile, rinforzare una scatola fragile o usare una confezione più piccola se disponibile. Non tutte le richieste possono essere soddisfatte; non chiedere di ignorare restrizioni o regole doganali. Per articoli sensibili o fragili, batterie, liquidi o dimensioni insolite, verifica le condizioni attuali prima di aggiungerli al pacco.","pt":"Faça pedidos de reembalagem específicos: reduzir embalagem desnecessária, reforçar uma caixa frágil ou usar embalagem menor, se disponível. Nem todos os pedidos podem ser cumpridos; não peça para ignorar restrições ou regras aduaneiras. Para artigos sensíveis ou frágeis, baterias, líquidos ou dimensões incomuns, consulte as condições atuais antes de os incluir no pacote.","nl":"Maak verzoeken voor herverpakking concreet: minder onnodige verpakking, een kwetsbare doos versterken of indien mogelijk kleiner verpakken. Niet elk verzoek kan worden uitgevoerd; vraag niet om routebeperkingen of douaneregels te omzeilen. Controleer bij gevoelige of breekbare goederen, batterijen, vloeistoffen of afwijkende afmetingen eerst de actuele routevoorwaarden.","pl":"Formułuj konkretne prośby o przepakowanie: ograniczenie zbędnych opakowań, wzmocnienie delikatnego kartonu lub mniejsze opakowanie, jeśli jest dostępne. Nie każdą prośbę da się spełnić; nie proś o omijanie ograniczeń trasy ani zasad celnych. Przed dodaniem delikatnych lub wrażliwych towarów, baterii, płynów czy przedmiotów o nietypowych wymiarach sprawdź aktualne warunki trasy.","sv":"Formulera ompackningsönskemål tydligt: minska onödig förpackning, förstärk en ömtålig kartong eller använd mindre förpackning om möjligt. Alla önskemål kan inte uppfyllas; be inte lagret kringgå ruttbegränsningar eller tullregler. Kontrollera aktuella ruttvillkor innan känsliga eller ömtåliga varor, batterier, vätskor eller ovanliga mått läggs i paketet."},"Searches for “PikoBuy link” and “PikoBuy product link” usually come from a simple need: move a product from a Chinese marketplace into a purchase form without accidentally changing the item. The official guide says users can paste a product link or keywords, but the order still depends on the options entered at checkout. A title can be shortened, a source picture can be reused, and a seller can change available sizes after a spreadsheet row was created.":{"de":"Wer nach „PikoBuy link“ oder „PikoBuy product link“ sucht, möchte meist einen Artikel aus einem chinesischen Marktplatz in ein Bestellformular übernehmen, ohne ihn versehentlich zu verändern. Laut Leitfaden lassen sich Links oder Suchbegriffe einfügen; die Bestellung hängt aber von den gewählten Optionen ab. Titel können gekürzt, Bilder wiederverwendet und Größen nach Erstellung einer Spreadsheet-Zeile geändert werden.","fr":"Les recherches « PikoBuy link » et « PikoBuy product link » visent souvent à transférer un article d’une place de marché chinoise dans un formulaire sans le modifier. Le guide autorise les liens ou mots-clés, mais la commande dépend des options choisies. Un titre peut être abrégé, une image réutilisée et les tailles modifiées après la création de la ligne du tableur.","es":"Las búsquedas «PikoBuy link» y «PikoBuy product link» suelen buscar pasar un artículo de un mercado chino al formulario sin cambiarlo por error. La guía permite pegar enlaces o palabras clave, pero el pedido depende de las opciones elegidas. Un título puede abreviarse, una foto reutilizarse y las tallas cambiar después de crear la fila.","it":"Le ricerche «PikoBuy link» e «PikoBuy product link» servono spesso a trasferire un articolo da un marketplace cinese nel modulo senza cambiarlo per errore. La guida consente link o parole chiave, ma l’ordine dipende dalle opzioni scelte. Il titolo può essere abbreviato, una foto riutilizzata e le taglie cambiare dopo la creazione della riga.","pt":"As pesquisas «PikoBuy link» e «PikoBuy product link» procuram muitas vezes transferir um artigo de um mercado chinês para o formulário sem o alterar por engano. O guia permite ligações ou palavras-chave, mas a encomenda depende das opções escolhidas. O título pode ser abreviado, uma foto reutilizada e os tamanhos alterados depois de criada a linha.","nl":"Zoekopdrachten naar “PikoBuy link” en “PikoBuy product link” gaan vaak over een artikel van een Chinese marktplaats naar een bestelformulier overbrengen zonder het per ongeluk te wijzigen. Volgens de gids kun je een link of zoekwoorden invoeren, maar de bestelling hangt af van de gekozen opties. Een titel kan worden ingekort, een foto hergebruikt en beschikbare maten kunnen na het maken van de spreadsheetregel veranderen.","pl":"Wyszukiwania „PikoBuy link” i „PikoBuy product link” zwykle dotyczą przeniesienia produktu z chińskiej platformy do formularza bez przypadkowej zmiany. Poradnik dopuszcza linki lub słowa kluczowe, ale zamówienie zależy od wybranych opcji. Tytuł może być skrócony, zdjęcie ponownie użyte, a rozmiary zmienione po utworzeniu wiersza arkusza.","sv":"Sökningar efter ”PikoBuy link” och ”PikoBuy product link” handlar ofta om att flytta en vara från en kinesisk marknadsplats till ett beställningsformulär utan att ändra den av misstag. Guiden tillåter länkar eller sökord, men beställningen beror på valda alternativ. En titel kan förkortas, en bild återanvändas och storlekar ändras efter att kalkylbladsraden skapats."},"Before pasting a link, record the information that cannot be inferred from the URL: the colour name, the exact size, whether the seller lists a batch or version, and any visible size-chart measurement. If a listing is priced as a deposit, pre-sale or multiple-option range, do not assume the first shown price is the final product price. The purchasing page is the place to review the selected specification one more time.":{"de":"Notiere vor dem Einfügen Angaben, die nicht aus der URL hervorgehen: Farbname, genaue Größe, gegebenenfalls Charge oder Version und sichtbare Maße der Größentabelle. Bei Anzahlung, Vorverkauf oder Preisspanne für mehrere Optionen ist der erste Preis nicht unbedingt der Endpreis. Prüfe die gewählte Ausführung nochmals auf der Bestellseite.","fr":"Avant de coller le lien, notez ce que l’URL ne révèle pas : nom de couleur, taille exacte, éventuel lot ou version et mesures visibles du tableau. En cas d’acompte, de prévente ou de fourchette selon les options, le premier prix affiché n’est pas forcément le prix final. Vérifiez encore la variante sur la page d’achat.","es":"Antes de pegar el enlace, anota lo que la URL no indica: color, talla exacta, lote o versión si aparece y medidas visibles de la tabla. Si el precio es un depósito, preventa o rango según opciones, el primero mostrado no tiene por qué ser el final. Revisa otra vez la variante en la página de compra.","it":"Prima di incollare il link annota ciò che l’URL non mostra: colore, taglia esatta, eventuale lotto o versione e misure visibili della tabella. Se il prezzo è un deposito, una prevendita o un intervallo per più opzioni, il primo importo non è necessariamente quello finale. Ricontrolla la variante nella pagina d’acquisto.","pt":"Antes de colar a ligação, registe o que o URL não indica: cor, tamanho exato, eventual lote ou versão e medidas visíveis da tabela. Se o preço for depósito, pré-venda ou intervalo para várias opções, o primeiro valor pode não ser o final. Confirme novamente a variante na página de compra.","nl":"Noteer vóór het plakken wat niet uit de URL blijkt: kleurnaam, exacte maat, eventuele batch of versie en zichtbare maten in de tabel. Bij een aanbetaling, voorverkoop of prijsklasse voor meerdere opties is de eerst getoonde prijs niet noodzakelijk de eindprijs. Controleer de gekozen uitvoering opnieuw op de aankooppagina.","pl":"Przed wklejeniem linku zapisz informacje niewynikające z URL: nazwę koloru, dokładny rozmiar, ewentualną partię lub wersję i widoczne wymiary z tabeli. Przy zaliczce, przedsprzedaży lub przedziale cen dla wariantów pierwsza cena nie musi być końcowa. Ponownie sprawdź wariant na stronie zakupu.","sv":"Skriv före inklistringen upp det som inte framgår av länken: färgnamn, exakt storlek, eventuell batch eller version och synliga mått i tabellen. Vid deposition, förhandsköp eller prisintervall för olika alternativ är det första priset inte nödvändigtvis slutpriset. Kontrollera vald variant igen på köpsidan."},"Product images should be used with the same care. Compare the source image set with the gallery shown in the product-detail page. Look for differences in logos, material panels, colour tone, quantity and included accessories. A source image can help identify the intended version; it cannot prove that a seller will deliver a specific quality level, that a brand claim is accurate, or that the item is lawful to import.":{"de":"Prüfe auch Bilder sorgfältig. Vergleiche Quellbilder mit der Galerie auf der Produktdetailseite und achte auf Logos, Materialteile, Farbton, Menge und Zubehör. Ein Quellbild hilft bei der Zuordnung der Version, beweist aber weder die gelieferte Qualität noch die Richtigkeit einer Markenangabe oder die rechtmäßige Einfuhr.","fr":"Examinez aussi les images avec soin. Comparez les photos source à la galerie de la fiche produit : logos, panneaux de matière, teinte, quantité et accessoires. Une image aide à identifier la version, mais ne prouve ni la qualité livrée, ni l’exactitude d’une mention de marque, ni la légalité de l’importation.","es":"Revisa también las imágenes con cuidado. Compara las fotos originales con la galería de la ficha: logotipos, paneles de material, tono, cantidad y accesorios. Una imagen ayuda a identificar la versión, pero no demuestra la calidad entregada, la veracidad de una marca ni la legalidad de importación.","it":"Controlla anche le immagini con attenzione. Confronta le foto originali con la galleria della scheda: loghi, pannelli di materiale, tonalità, quantità e accessori. Un’immagine aiuta a identificare la versione, ma non dimostra qualità consegnata, correttezza delle indicazioni di marca o liceità dell’importazione.","pt":"Verifique também as imagens com cuidado. Compare as fotos de origem com a galeria da ficha: logótipos, painéis de material, tom, quantidade e acessórios. Uma imagem ajuda a identificar a versão, mas não prova a qualidade entregue, a veracidade de uma marca nem a legalidade da importação.","nl":"Bekijk ook afbeeldingen zorgvuldig. Vergelijk de bronfoto’s met de galerij op de productpagina en let op logo’s, materiaalvlakken, kleurtoon, aantal en accessoires. Een bronfoto helpt de versie te herkennen, maar bewijst niet welke kwaliteit wordt geleverd, of een merkclaim klopt of invoer is toegestaan.","pl":"Równie starannie sprawdzaj zdjęcia. Porównaj zdjęcia źródłowe z galerią szczegółów: logo, elementy materiału, odcień, ilość i akcesoria. Zdjęcie pomaga rozpoznać wersję, ale nie dowodzi jakości dostawy, prawdziwości informacji o marce ani legalności importu.","sv":"Granska även bilder noggrant. Jämför källbilder med galleriet på produktsidan: logotyper, materialpaneler, färgton, antal och tillbehör. En källbild hjälper till att identifiera versionen men bevisar inte levererad kvalitet, att ett varumärkespåstående är korrekt eller att importen är tillåten."},"The phrase “PikoBuy return policy” needs a precise answer. PikoBuy's public Returns & Exchanges page says that a qualifying item can be requested within five days, or 120 hours, after the order status becomes In Warehouse. The page also explains that eligibility depends on the seller's return guarantee, the resale condition of the item and the product category.":{"de":"Für „PikoBuy return policy“ ist eine genaue Antwort wichtig. Die öffentliche Rückgabe- und Umtauschseite nennt für geeignete Artikel einen Antrag innerhalb von fünf Tagen beziehungsweise 120 Stunden ab Status „In Warehouse“. Die Berechtigung hängt auch von der Rückgabegarantie des Verkäufers, dem Wiederverkaufszustand und der Produktkategorie ab.","fr":"La question « PikoBuy return policy » exige une réponse précise. La page publique Retours et échanges prévoit une demande pour un article admissible dans les cinq jours, soit 120 heures, après le statut « In Warehouse ». L’admissibilité dépend aussi de la garantie du vendeur, de l’état permettant la revente et de la catégorie.","es":"La consulta «PikoBuy return policy» requiere precisión. La página pública de devoluciones y cambios indica que puede solicitarse la devolución de un artículo elegible dentro de cinco días o 120 horas desde el estado «In Warehouse». La elegibilidad depende también de la garantía del vendedor, el estado de reventa y la categoría.","it":"La ricerca «PikoBuy return policy» richiede precisione. La pagina pubblica Resi e cambi indica che per un articolo idoneo si può fare richiesta entro cinque giorni, o 120 ore, dallo stato «In Warehouse». L’idoneità dipende anche dalla garanzia del venditore, dalle condizioni di rivendita e dalla categoria.","pt":"A pesquisa «PikoBuy return policy» exige precisão. A página pública de devoluções e trocas indica que um artigo elegível pode ser solicitado para devolução em cinco dias, ou 120 horas, após o estado «In Warehouse». A elegibilidade depende também da garantia do vendedor, das condições de revenda e da categoria.","nl":"De vraag “PikoBuy return policy” vraagt een nauwkeurig antwoord. De openbare retour- en ruilpagina noemt voor een geschikt artikel een aanvraag binnen vijf dagen of 120 uur na de status “In Warehouse”. De voorwaarden hangen ook af van de retourgarantie van de verkoper, de staat voor wederverkoop en de productcategorie.","pl":"Pytanie „PikoBuy return policy” wymaga precyzji. Publiczna strona zwrotów i wymian podaje, że dla kwalifikującego się produktu można złożyć wniosek w ciągu pięciu dni, czyli 120 godzin, od statusu „In Warehouse”. Uprawnienie zależy także od gwarancji sprzedawcy, stanu umożliwiającego odsprzedaż i kategorii produktu.","sv":"Frågan ”PikoBuy return policy” kräver ett exakt svar. Den offentliga retur- och bytessidan anger att en begäran för en berättigad vara kan göras inom fem dagar, eller 120 timmar, efter statusen ”In Warehouse”. Rätten beror även på säljarens returvillkor, varans skick för återförsäljning och produktkategori."},"That time window is a reason to review warehouse photos promptly. Waiting until a parcel is already submitted can remove practical options. The published policy lists examples of items that may not be returnable or that require unopened packaging, including custom goods, some personal items, second-hand goods and specified sealed categories. A return is not the same thing as a shipping cancellation, and seller acceptance can still matter.":{"de":"Diese Frist ist ein Grund, Lagerfotos schnell zu prüfen. Nach Einreichung eines Pakets können praktische Möglichkeiten entfallen. Die veröffentlichte Richtlinie nennt nicht rückgabefähige oder nur ungeöffnet rückgabefähige Waren, darunter Sonderanfertigungen, bestimmte persönliche und gebrauchte Artikel sowie manche versiegelte Kategorien. Rückgabe ist keine Versandstornierung; die Zustimmung des Verkäufers kann relevant sein.","fr":"Ce délai justifie un examen rapide des photos d’entrepôt. Attendre la soumission du colis peut réduire les possibilités. La politique cite des articles non retournables ou exigeant un emballage intact : articles personnalisés, certains effets personnels, occasions et catégories scellées. Un retour diffère d’une annulation d’expédition et l’accord du vendeur peut rester nécessaire.","es":"Este plazo hace importante revisar pronto las fotos del almacén. Esperar hasta enviar el paquete puede reducir las opciones. La política cita artículos no retornables o que requieren embalaje sin abrir: personalizados, algunos artículos personales, usados y categorías selladas. Una devolución no es una cancelación de envío y puede requerir aceptación del vendedor.","it":"La scadenza rende importante controllare presto le foto del magazzino. Attendere l’invio del pacco può ridurre le possibilità. La politica cita articoli non restituibili o con confezione intatta: personalizzati, alcuni articoli personali, usati e categorie sigillate. Un reso non è una cancellazione della spedizione e può servire l’accettazione del venditore.","pt":"Este prazo torna importante verificar cedo as fotos do armazém. Esperar até submeter o pacote pode reduzir as opções. A política cita artigos não devolvíveis ou que exigem embalagem intacta: personalizados, alguns artigos pessoais, usados e categorias seladas. Uma devolução não é cancelamento de envio e pode depender da aceitação do vendedor.","nl":"Deze termijn maakt snelle controle van magazijnfoto’s belangrijk. Wachten tot het pakket is ingediend kan mogelijkheden wegnemen. Het beleid noemt artikelen die niet retour kunnen of ongeopende verpakking vereisen, waaronder maatwerk, sommige persoonlijke en tweedehands artikelen en verzegelde categorieën. Een retour is geen verzendannulering; instemming van de verkoper kan nodig zijn.","pl":"Termin jest powodem szybkiego sprawdzenia zdjęć magazynowych. Oczekiwanie do zgłoszenia paczki może ograniczyć możliwości. Polityka wymienia towary bezzwrotne lub wymagające nieotwartego opakowania, w tym produkty personalizowane, niektóre osobiste, używane i wybrane zapieczętowane. Zwrot nie jest anulowaniem wysyłki; zgoda sprzedawcy może być potrzebna.","sv":"Tidsfristen gör det viktigt att granska lagerbilder snabbt. Om man väntar tills paketet lämnats in kan möjligheter försvinna. Policyn nämner varor som inte kan returneras eller kräver oöppnad förpackning, bland annat specialbeställningar, vissa personliga och begagnade varor samt förseglade kategorier. Retur är inte samma sak som att avbryta frakt; säljarens godkännande kan krävas."},"Costs can depend on why the return is requested. PikoBuy's published page notes that a personal-reason return can involve return shipping, the seller's original shipping charge and a service fee, while a seller-caused issue may be handled differently. These facts should be read on the live policy page immediately before an application, since eligibility and charges can change.":{"de":"Die Kosten hängen vom Rückgabegrund ab. Laut veröffentlichter PikoBuy-Seite können bei persönlichen Gründen Rückversand, ursprüngliche Verkäufer-Versandkosten und eine Servicegebühr anfallen; ein vom Verkäufer verursachtes Problem kann anders behandelt werden. Lies vor dem Antrag die aktuelle Richtlinie, da Bedingungen und Gebühren sich ändern können.","fr":"Les coûts dépendent du motif. Selon la page publiée par PikoBuy, un retour pour convenance personnelle peut entraîner les frais de retour, le transport initial du vendeur et des frais de service ; un problème imputable au vendeur peut être traité autrement. Consultez la politique actuelle avant la demande, car conditions et frais peuvent changer.","es":"Los costes dependen del motivo. Según la página publicada de PikoBuy, una devolución por motivos personales puede incluir envío de retorno, envío original del vendedor y tarifa de servicio; un problema causado por el vendedor puede tratarse de otra manera. Consulta la política vigente antes de solicitarla, pues condiciones y cargos pueden cambiar.","it":"I costi dipendono dal motivo. Secondo la pagina pubblicata da PikoBuy, un reso per motivi personali può includere spedizione di ritorno, spedizione originale del venditore e commissione di servizio; un problema causato dal venditore può essere gestito diversamente. Consulta la politica attuale prima della richiesta: condizioni e costi possono cambiare.","pt":"Os custos dependem do motivo. Segundo a página publicada da PikoBuy, uma devolução por motivos pessoais pode incluir envio de retorno, envio original do vendedor e taxa de serviço; um problema causado pelo vendedor pode ser tratado de outra forma. Consulte a política atual antes do pedido, pois condições e taxas podem mudar.","nl":"De kosten hangen af van de reden. Volgens de gepubliceerde PikoBuy-pagina kunnen bij een persoonlijke reden retourverzending, oorspronkelijke verzendkosten van de verkoper en servicekosten gelden; een probleem door de verkoper kan anders worden behandeld. Lees het actuele beleid vóór de aanvraag: voorwaarden en kosten kunnen veranderen.","pl":"Koszty zależą od przyczyny. Według opublikowanej strony PikoBuy zwrot z przyczyn osobistych może obejmować przesyłkę zwrotną, pierwotną wysyłkę sprzedawcy i opłatę serwisową; problem spowodowany przez sprzedawcę może być rozpatrzony inaczej. Przed wnioskiem sprawdź aktualną politykę, ponieważ warunki i opłaty mogą się zmienić.","sv":"Kostnaden beror på orsaken. Enligt PikoBuys publicerade sida kan en retur av personliga skäl medföra returfrakt, säljarens ursprungliga frakt och serviceavgift; fel orsakat av säljaren kan hanteras annorlunda. Läs aktuell policy före ansökan eftersom villkor och avgifter kan ändras."},"“PikoBuy tracking” is most useful when it separates an order status from a carrier scan. PikoBuy's shopping guide says tracking information is normally available within three days after a parcel has been shipped. That does not mean every international parcel will show a detailed movement immediately; carrier intake, export processing and handoffs can create a delay before the first meaningful scan appears.":{"de":"Bei „PikoBuy tracking“ sollte man Bestellstatus und Scan des Versanddienstes unterscheiden. Laut Einkaufsleitfaden sind Sendungsdaten normalerweise innerhalb von drei Tagen nach Versand verfügbar. Detaillierte Bewegungen erscheinen nicht immer sofort: Übernahme, Ausfuhr und Übergaben können den ersten aussagekräftigen Scan verzögern.","fr":"Pour « PikoBuy tracking », distinguez le statut de commande du scan du transporteur. Le guide indique que le suivi est normalement disponible dans les trois jours suivant l’expédition. Les mouvements détaillés ne sont pas toujours immédiats : prise en charge, export et transferts peuvent retarder le premier scan utile.","es":"En «PikoBuy tracking» conviene distinguir el estado del pedido del escaneo del transportista. La guía indica que el seguimiento suele estar disponible en los tres días posteriores al envío. Los movimientos detallados no siempre aparecen enseguida: recepción, exportación y traspasos pueden retrasar el primer escaneo útil.","it":"Per «PikoBuy tracking» distingui lo stato dell’ordine dalla scansione del corriere. La guida indica che il tracciamento è normalmente disponibile entro tre giorni dalla spedizione. I movimenti dettagliati non compaiono sempre subito: presa in carico, esportazione e passaggi possono ritardare la prima scansione utile.","pt":"Em «PikoBuy tracking», distinga o estado da encomenda do registo da transportadora. O guia indica que o rastreio fica normalmente disponível até três dias após o envio. Os movimentos detalhados nem sempre aparecem imediatamente: receção, exportação e transferências podem atrasar o primeiro registo útil.","nl":"Bij “PikoBuy tracking” is onderscheid tussen bestelstatus en scan van de vervoerder belangrijk. Volgens de gids is tracking normaal binnen drie dagen na verzending beschikbaar. Gedetailleerde bewegingen verschijnen niet altijd direct: inname, export en overdracht kunnen de eerste bruikbare scan vertragen.","pl":"Przy „PikoBuy tracking” rozróżnij status zamówienia od skanu przewoźnika. Poradnik podaje, że śledzenie jest zwykle dostępne w ciągu trzech dni po wysłaniu. Szczegółowy ruch nie zawsze pojawia się od razu: przyjęcie, eksport i przekazania mogą opóźnić pierwszy przydatny skan.","sv":"Vid ”PikoBuy tracking” bör orderstatus skiljas från transportörens skanning. Guiden anger att spårning normalt blir tillgänglig inom tre dagar efter avsändning. Detaljerade rörelser syns inte alltid direkt: mottagning, export och överlämningar kan fördröja den första användbara skanningen."},"Start with the actual parcel status and the tracking number in the shipping order. Check the destination address and route information before assuming that a quiet tracking page means a parcel is lost. A lack of movement during an early handoff can simply reflect the carrier's scan schedule. Conversely, a visible number should not be treated as proof of a guaranteed delivery date.":{"de":"Prüfe zuerst Paketstatus und Sendungsnummer der Versandbestellung. Kontrolliere Zieladresse und Route, bevor du aus einer ruhigen Trackingseite auf Verlust schließt. Fehlende Bewegung bei einer frühen Übergabe kann am Scanrhythmus liegen. Eine sichtbare Nummer garantiert umgekehrt keinen Liefertermin.","fr":"Commencez par le statut réel et le numéro de suivi du colis. Vérifiez l’adresse et la ligne avant de conclure qu’un suivi silencieux signifie une perte. Une absence de mouvement au début peut refléter le calendrier de scan. Un numéro visible ne garantit pas non plus une date de livraison.","es":"Empieza por el estado real y el número de seguimiento del paquete. Comprueba dirección y ruta antes de concluir que la falta de novedades significa pérdida. La ausencia de movimiento durante un traspaso inicial puede reflejar el calendario de escaneos. Un número visible tampoco garantiza fecha de entrega.","it":"Parti dallo stato effettivo e dal numero di tracciamento del pacco. Controlla indirizzo e rotta prima di considerare perso un pacco senza aggiornamenti. L’assenza di movimenti in un passaggio iniziale può dipendere dalle scansioni. Un numero visibile non garantisce una data di consegna.","pt":"Comece pelo estado real e pelo número de rastreio do pacote. Confirme morada e rota antes de concluir que a ausência de atualizações significa perda. A falta de movimento numa transferência inicial pode refletir o calendário de registos. Um número visível também não garante data de entrega.","nl":"Begin met de werkelijke pakketstatus en het trackingnummer. Controleer bestemming en route voordat je stilte op de trackingpagina als verlies ziet. Geen beweging bij een vroege overdracht kan door het scanschema komen. Een zichtbaar nummer garandeert evenmin een leverdatum.","pl":"Zacznij od rzeczywistego statusu i numeru śledzenia paczki. Sprawdź adres oraz trasę, zanim uznasz brak aktualizacji za zaginięcie. Brak ruchu przy wczesnym przekazaniu może wynikać z harmonogramu skanowania. Widoczny numer nie gwarantuje też daty dostawy.","sv":"Börja med paketets faktiska status och spårningsnummer. Kontrollera adress och rutt innan tyst spårning tolkas som förlust. Utebliven rörelse vid en tidig överlämning kan bero på skanningsschemat. Ett synligt nummer garanterar inte heller ett leveransdatum."},"Keep records that make a support request clear: the parcel number, route name, first-shipment date, tracking screenshots and a concise description of the issue. PikoBuy's terms say international delivery involves third-party logistics providers and that claims follow the relevant provider's standards. Precise information helps when support needs to communicate with a carrier.":{"de":"Halte für eine klare Supportanfrage Paketnummer, Routenname, Versanddatum, Tracking-Screenshots und eine kurze Problembeschreibung bereit. Laut PikoBuy sind Drittanbieter an internationalen Lieferungen beteiligt und Ansprüche folgen deren Maßstäben. Genaue Angaben helfen dem Support bei der Kommunikation mit dem Versanddienst.","fr":"Pour une demande claire, conservez numéro de colis, nom de la ligne, date d’expédition, captures du suivi et brève description du problème. Les conditions PikoBuy indiquent que des prestataires tiers interviennent et que leurs règles s’appliquent aux réclamations. Ces précisions aident le support à contacter le transporteur.","es":"Para una consulta clara conserva número de paquete, ruta, fecha de envío, capturas del seguimiento y descripción breve del problema. Las condiciones de PikoBuy indican que intervienen proveedores externos y que las reclamaciones siguen sus normas. Los datos precisos ayudan al soporte a comunicarse con el transportista.","it":"Per una richiesta chiara conserva numero del pacco, rotta, data di spedizione, schermate del tracciamento e breve descrizione del problema. Le condizioni PikoBuy prevedono fornitori terzi e reclami secondo le loro regole. Dati precisi aiutano l’assistenza a comunicare con il corriere.","pt":"Para um pedido claro, guarde número do pacote, rota, data de envio, capturas do rastreio e breve descrição do problema. As condições da PikoBuy indicam prestadores externos e reclamações segundo as regras destes. Dados precisos ajudam o apoio a comunicar com a transportadora.","nl":"Bewaar voor een duidelijk supportverzoek pakketnummer, routenaam, verzenddatum, screenshots van tracking en een korte probleembeschrijving. Volgens de PikoBuy-voorwaarden verzorgen derden de internationale levering en volgen claims hun regels. Precieze gegevens helpen support bij contact met de vervoerder.","pl":"Do jasnego zgłoszenia zachowaj numer paczki, nazwę trasy, datę wysyłki, zrzuty śledzenia i krótki opis problemu. Warunki PikoBuy wskazują udział zewnętrznych przewoźników i rozpatrywanie roszczeń według ich zasad. Dokładne dane pomagają wsparciu w kontakcie z przewoźnikiem.","sv":"Spara paketnummer, ruttnamn, avsändningsdatum, skärmbilder av spårningen och en kort problembeskrivning för ett tydligt supportärende. PikoBuys villkor anger att externa transportörer deltar och att krav följer deras regler. Exakta uppgifter hjälper supporten i kontakten med transportören."},"International-forwarding content should not promise that a parcel will clear customs, arrive on a date or be accepted by every route. PikoBuy's shipping terms state that cross-border parcels use third-party logistics providers and that risks such as customs policies, loss, damage and peak-season delays are unavoidable. The terms advise users to assess those risks before choosing a route.":{"de":"Internationale Versandhinweise sollten weder Zollfreigabe, einen festen Liefertermin noch die Annahme durch jede Route versprechen. PikoBuys Versandbedingungen nennen externe Logistikdienstleister und unvermeidbare Risiken wie Zollbestimmungen, Verlust, Schäden und Verzögerungen in Spitzenzeiten. Nutzer sollen diese vor der Routenwahl bewerten.","fr":"Les conseils d’expédition internationale ne doivent promettre ni dédouanement, ni date fixe, ni acceptation sur toutes les lignes. Les conditions PikoBuy mentionnent des prestataires tiers et des risques inévitables : règles douanières, perte, dommages et retards en période chargée. Elles invitent à les évaluer avant de choisir une ligne.","es":"Una guía de envío internacional no debe prometer despacho de aduanas, fecha fija ni aceptación en todas las rutas. Las condiciones de PikoBuy mencionan proveedores externos y riesgos inevitables como normas aduaneras, pérdida, daños y retrasos en temporada alta. Recomiendan evaluarlos antes de elegir ruta.","it":"Una guida alla spedizione internazionale non deve promettere sdoganamento, data certa o accettazione su ogni rotta. Le condizioni PikoBuy indicano fornitori terzi e rischi inevitabili come norme doganali, smarrimento, danni e ritardi nei periodi di punta. Invitano a valutarli prima di scegliere la rotta.","pt":"Um guia de envio internacional não deve prometer desalfandegamento, data fixa ou aceitação em todas as rotas. As condições da PikoBuy referem prestadores externos e riscos inevitáveis como regras aduaneiras, perda, danos e atrasos na época alta. Recomendam avaliá-los antes de escolher a rota.","nl":"Informatie over internationale verzending mag geen douanevrijgave, vaste leverdatum of acceptatie op elke route beloven. De PikoBuy-voorwaarden noemen externe vervoerders en onvermijdelijke risico’s zoals douanebeleid, verlies, schade en vertraging in drukke perioden. Beoordeel die risico’s vóór de routekeuze.","pl":"Poradnik wysyłki międzynarodowej nie powinien obiecywać odprawy celnej, konkretnej daty ani przyjęcia każdą trasą. Warunki PikoBuy wskazują zewnętrznych przewoźników i nieuniknione ryzyka: przepisy celne, zagubienie, uszkodzenie oraz opóźnienia sezonowe. Zalecają ich ocenę przed wyborem trasy.","sv":"Information om internationell frakt ska inte lova tullklarering, ett visst leveransdatum eller godkännande på varje rutt. PikoBuys villkor nämner externa logistikföretag och oundvikliga risker som tullregler, förlust, skador och högsäsongsförseningar. Bedöm riskerna före ruttvalet."},"Begin with the item itself. Batteries, liquids, powders, food, medicines, fragile goods and products with special restrictions can have different route eligibility. PikoBuy's published terms also describe prohibited items and intellectual-property restrictions. A spreadsheet row or product image does not override a carrier rule, destination law or platform policy.":{"de":"Beginne beim Artikel: Batterien, Flüssigkeiten, Pulver, Lebensmittel, Medikamente, zerbrechliche und besonders beschränkte Waren können unterschiedliche Routenvorgaben haben. PikoBuys Bedingungen nennen zudem verbotene Waren und Beschränkungen zum geistigen Eigentum. Eine Spreadsheet-Zeile oder ein Foto setzt weder Transportregel, Ziellandrecht noch Plattformrichtlinie außer Kraft.","fr":"Commencez par l’article : batteries, liquides, poudres, aliments, médicaments, objets fragiles et produits soumis à restrictions peuvent avoir des lignes autorisées différentes. Les conditions PikoBuy mentionnent aussi des interdictions et restrictions de propriété intellectuelle. Une ligne de tableur ou une image ne remplace ni règle du transporteur, ni loi locale, ni politique de plateforme.","es":"Empieza por el artículo: baterías, líquidos, polvos, alimentos, medicamentos, objetos frágiles y productos restringidos pueden tener rutas permitidas diferentes. Las condiciones de PikoBuy también describen prohibiciones y restricciones de propiedad intelectual. Una fila o imagen no anula las reglas del transportista, la ley del destino ni la política de la plataforma.","it":"Parti dall’articolo: batterie, liquidi, polveri, alimenti, medicinali, oggetti fragili e prodotti soggetti a restrizioni possono avere rotte ammesse diverse. Le condizioni PikoBuy descrivono anche divieti e limiti sulla proprietà intellettuale. Una riga o un’immagine non prevale su regole del corriere, legge di destinazione o politica della piattaforma.","pt":"Comece pelo artigo: baterias, líquidos, pós, alimentos, medicamentos, objetos frágeis e produtos restritos podem ter rotas permitidas diferentes. As condições da PikoBuy descrevem também proibições e limites de propriedade intelectual. Uma linha ou imagem não substitui regras da transportadora, lei de destino ou política da plataforma.","nl":"Begin bij het artikel: batterijen, vloeistoffen, poeders, voedsel, medicijnen, breekbare en beperkt toegestane goederen kunnen verschillende routevoorwaarden hebben. De PikoBuy-voorwaarden noemen ook verboden goederen en intellectuele-eigendomsbeperkingen. Een spreadsheetregel of afbeelding gaat niet boven vervoerdersregels, bestemmingswetgeving of platformbeleid.","pl":"Zacznij od produktu: baterie, płyny, proszki, żywność, leki, delikatne towary i artykuły objęte ograniczeniami mogą mieć różne dostępne trasy. Warunki PikoBuy opisują też zakazy i ograniczenia własności intelektualnej. Wiersz arkusza ani zdjęcie nie znoszą zasad przewoźnika, prawa kraju docelowego ani polityki platformy.","sv":"Börja med varan: batterier, vätskor, pulver, livsmedel, läkemedel, ömtåliga och särskilt begränsade produkter kan ha olika tillåtna rutter. PikoBuys villkor beskriver även förbjudna varor och immaterialrättsliga begränsningar. En kalkylbladsrad eller bild upphäver inte transportörens regler, destinationslandets lagar eller plattformens policy."},"Next, review the destination and declaration information carefully. Use the current official route descriptions rather than advice copied from an old social post. Customs rules, import duties and carrier handling can differ by country and change over time. If an item is not clearly allowed, the responsible choice is to seek current information before paying for shipment.":{"de":"Prüfe Zielort und Deklarationsangaben sorgfältig. Nutze aktuelle offizielle Routenbeschreibungen statt alter Social-Media-Ratschläge. Zollregeln, Einfuhrabgaben und die Bearbeitung durch den Transporteur unterscheiden sich je nach Land und können sich ändern. Ist ein Artikel nicht eindeutig zulässig, kläre die aktuellen Vorgaben vor Zahlung des Versands.","fr":"Vérifiez soigneusement la destination et la déclaration. Utilisez les descriptions officielles actuelles plutôt que d’anciens conseils sociaux. Règles douanières, droits et traitement par le transporteur varient selon les pays et évoluent. Si un article n’est pas clairement autorisé, renseignez-vous avant de payer l’expédition.","es":"Revisa cuidadosamente destino y declaración. Usa descripciones oficiales actuales en lugar de consejos antiguos de redes. Las normas aduaneras, aranceles y gestión del transportista varían por país y pueden cambiar. Si no está claro que un artículo esté permitido, consulta la información actual antes de pagar el envío.","it":"Controlla attentamente destinazione e dichiarazione. Usa le descrizioni ufficiali attuali, non vecchi consigli social. Regole doganali, dazi e gestione del corriere variano per paese e possono cambiare. Se un articolo non è chiaramente ammesso, verifica le informazioni attuali prima di pagare la spedizione.","pt":"Reveja cuidadosamente destino e declaração. Use descrições oficiais atuais em vez de conselhos antigos das redes sociais. Regras aduaneiras, direitos e tratamento pela transportadora variam por país e podem mudar. Se não for claro que um artigo é permitido, consulte a informação atual antes de pagar o envio.","nl":"Controleer bestemming en aangifte zorgvuldig. Gebruik actuele officiële routebeschrijvingen in plaats van oude adviezen op sociale media. Douaneregels, invoerrechten en afhandeling door vervoerders verschillen per land en kunnen veranderen. Is een artikel niet duidelijk toegestaan, zoek dan actuele informatie vóór betaling van verzending.","pl":"Dokładnie sprawdź kraj docelowy i deklarację. Korzystaj z aktualnych oficjalnych opisów tras zamiast starych porad z mediów społecznościowych. Przepisy celne, opłaty importowe i obsługa przewoźnika różnią się między krajami i mogą się zmieniać. Jeśli dopuszczalność produktu jest niejasna, sprawdź aktualne informacje przed opłaceniem wysyłki.","sv":"Granska destination och deklaration noggrant. Använd aktuella officiella ruttbeskrivningar i stället för gamla råd på sociala medier. Tullregler, importavgifter och transportörens hantering varierar mellan länder och kan ändras. Om det är oklart om en vara är tillåten, kontrollera aktuell information innan frakten betalas."},"People searching “PikoBuy size chart” or “PikoBuy spreadsheet” often need a way to reduce wrong-option orders. The useful approach is to read the source listing before the agent order is created. Confirm the seller's measurement chart, the selected size, the colour or version label and the visible condition of any pre-order or deposit notice.":{"de":"Wer nach „PikoBuy size chart“ oder „PikoBuy spreadsheet“ sucht, möchte häufig Fehlbestellungen vermeiden. Prüfe das Quellangebot vor der Agentenbestellung: Größentabelle, gewählte Größe, Farb- oder Versionsbezeichnung sowie sichtbare Vorverkaufs- oder Anzahlungsbedingungen.","fr":"Les recherches « PikoBuy size chart » ou « PikoBuy spreadsheet » visent souvent à éviter une mauvaise variante. Consultez l’annonce source avant la commande : tableau de mesures du vendeur, taille choisie, couleur ou version et éventuelles conditions de prévente ou d’acompte.","es":"Quienes buscan «PikoBuy size chart» o «PikoBuy spreadsheet» suelen querer evitar variantes equivocadas. Revisa el anuncio antes del pedido: tabla de medidas del vendedor, talla elegida, color o versión y posibles condiciones de preventa o depósito.","it":"Chi cerca «PikoBuy size chart» o «PikoBuy spreadsheet» vuole spesso evitare varianti errate. Leggi l’inserzione prima dell’ordine: tabella misure del venditore, taglia scelta, colore o versione ed eventuali condizioni di prevendita o deposito.","pt":"Quem pesquisa «PikoBuy size chart» ou «PikoBuy spreadsheet» procura evitar opções erradas. Leia o anúncio antes da encomenda: tabela de medidas do vendedor, tamanho escolhido, cor ou versão e eventuais condições de pré-venda ou depósito.","nl":"Wie zoekt naar “PikoBuy size chart” of “PikoBuy spreadsheet” wil vaak verkeerde opties vermijden. Lees de bronvermelding vóór de bestelling: maattabel van de verkoper, gekozen maat, kleur of versie en eventuele voorwaarden voor voorverkoop of aanbetaling.","pl":"Osoby szukające „PikoBuy size chart” lub „PikoBuy spreadsheet” chcą często uniknąć błędnego wariantu. Przeczytaj ofertę przed zamówieniem: tabelę wymiarów sprzedawcy, wybrany rozmiar, kolor lub wersję oraz widoczne warunki przedsprzedaży lub zaliczki.","sv":"Den som söker ”PikoBuy size chart” eller ”PikoBuy spreadsheet” vill ofta undvika fel variant. Läs källannonsen före beställning: säljarens måttabell, vald storlek, färg eller version och eventuella villkor för förhandsköp eller deposition."},"Letter sizes are not consistent between sellers. Where measurements are available, compare them with an item you already own and allow for the seller's stated tolerance. Do not describe a generic chart as a guarantee of fit. If the listing uses a translated title, check the source images and option labels as well; the product name can be less specific than the actual variant menu.":{"de":"Buchstabengrößen unterscheiden sich je nach Verkäufer. Vergleiche verfügbare Maße mit einem eigenen Kleidungsstück und beachte die angegebene Toleranz. Eine allgemeine Tabelle garantiert keine Passform. Bei übersetztem Titel auch Quellbilder und Varianten prüfen; der Produktname kann weniger genau sein als das Auswahlmenü.","fr":"Les tailles en lettres varient selon les vendeurs. Comparez les mesures disponibles à un vêtement que vous possédez et tenez compte de la tolérance indiquée. Un tableau générique ne garantit pas la coupe. Si le titre est traduit, vérifiez aussi images source et options : le nom peut être moins précis que le menu.","es":"Las tallas de letras varían entre vendedores. Compara las medidas disponibles con una prenda propia y considera la tolerancia indicada. Una tabla genérica no garantiza el ajuste. Si el título está traducido, revisa también las imágenes y opciones: el nombre puede ser menos preciso que el menú.","it":"Le taglie in lettere variano tra venditori. Confronta le misure disponibili con un capo che possiedi e considera la tolleranza indicata. Una tabella generica non garantisce la vestibilità. Se il titolo è tradotto, controlla anche immagini e opzioni: il nome può essere meno preciso del menu.","pt":"Os tamanhos por letras variam entre vendedores. Compare as medidas disponíveis com uma peça sua e considere a tolerância indicada. Uma tabela genérica não garante o ajuste. Se o título estiver traduzido, verifique imagens e opções: o nome pode ser menos preciso do que o menu.","nl":"Lettermaten verschillen per verkoper. Vergelijk beschikbare afmetingen met een eigen kledingstuk en houd rekening met de opgegeven tolerantie. Een algemene tabel garandeert geen pasvorm. Controleer bij een vertaalde titel ook bronfoto’s en opties: de productnaam kan minder precies zijn dan het keuzemenu.","pl":"Rozmiary literowe różnią się między sprzedawcami. Porównaj dostępne wymiary z własnym ubraniem i uwzględnij podaną tolerancję. Ogólna tabela nie gwarantuje dopasowania. Przy tłumaczonym tytule sprawdź też zdjęcia i opcje: nazwa może być mniej dokładna niż menu wariantów.","sv":"Bokstavsstorlekar varierar mellan säljare. Jämför tillgängliga mått med ett eget plagg och beakta säljarens angivna tolerans. En allmän tabell garanterar inte passform. Kontrollera även källbilder och alternativ vid översatt titel: produktnamnet kan vara mindre exakt än variantmenyn."},"Price deserves the same context. A displayed source price may represent a range, a deposit, a single option or a temporary promotion. Exchange-rate movement, domestic shipping, seller changes and service or parcel costs can all affect the amount paid at different stages. The product-detail page presents a USD comparison value, but the current transaction page is the place to verify live pricing.":{"de":"Auch Preise brauchen Kontext: Ein Quellpreis kann eine Spanne, Anzahlung, einzelne Option oder zeitlich begrenzte Aktion sein. Wechselkurs, Inlandsversand, Verkäuferänderungen sowie Service- und Paketkosten beeinflussen Zahlungen in verschiedenen Phasen. Die Produktseite zeigt einen USD-Vergleichswert; prüfe den aktuellen Preis auf der Transaktionsseite.","fr":"Le prix exige aussi du contexte : il peut s’agir d’une fourchette, d’un acompte, d’une option ou d’une promotion temporaire. Change, transport intérieur, modifications du vendeur, services et colis peuvent affecter les paiements successifs. La fiche affiche une valeur indicative en USD ; vérifiez le prix actuel sur la page de transaction.","es":"El precio también necesita contexto: puede ser un rango, depósito, una opción o promoción temporal. Tipo de cambio, envío nacional, cambios del vendedor y costes de servicio o paquete afectan a pagos en distintas etapas. La ficha muestra una referencia en USD; confirma el precio actual en la página de compra.","it":"Anche il prezzo richiede contesto: può indicare un intervallo, deposito, singola opzione o promozione temporanea. Cambio, spedizione interna, modifiche del venditore e costi di servizio o pacco influiscono sui pagamenti nelle varie fasi. La scheda mostra un riferimento USD; verifica il prezzo attuale nella transazione.","pt":"O preço também exige contexto: pode representar intervalo, depósito, uma opção ou promoção temporária. Câmbio, envio interno, alterações do vendedor e custos de serviço ou pacote afetam pagamentos em fases diferentes. A ficha apresenta uma referência em USD; confirme o preço atual na transação.","nl":"Ook de prijs vraagt context: de bronprijs kan een bereik, aanbetaling, enkele optie of tijdelijke actie zijn. Wisselkoers, binnenlandse verzending, wijzigingen van de verkoper en service- of pakketkosten beïnvloeden betalingen in verschillende fasen. De productpagina toont een USD-referentiewaarde; controleer de actuele prijs op de transactiepagina.","pl":"Cena także wymaga kontekstu: może oznaczać przedział, zaliczkę, jeden wariant lub czasową promocję. Kurs, wysyłka krajowa, zmiany sprzedawcy i koszty usług lub paczki wpływają na płatności w różnych etapach. Strona produktu pokazuje wartość porównawczą USD; aktualną cenę sprawdź przy transakcji.","sv":"Även priset behöver sammanhang: källpriset kan vara ett intervall, en deposition, ett alternativ eller en tillfällig kampanj. Växelkurs, inrikesfrakt, säljarändringar och service- eller paketkostnader påverkar betalningar i olika steg. Produktsidan visar ett jämförelsevärde i USD; kontrollera aktuellt pris på transaktionssidan."},"A first PikoBuy order is easier to manage when it is treated as several smaller checks. First, verify the source item: title, seller option, size, colour, images and whether the displayed price is for the actual variation. Second, submit the purchasing order only after those details are clear. PikoBuy's guide separates this purchasing stage from the later international-shipping payment.":{"de":"Eine erste PikoBuy-Bestellung wird übersichtlicher, wenn du sie in einzelne Prüfungen aufteilst. Prüfe zuerst Titel, Verkäuferoption, Größe, Farbe, Bilder und ob der Preis für die tatsächliche Variante gilt. Bestelle erst, wenn diese Angaben klar sind. PikoBuys Leitfaden trennt den Kauf von der späteren Zahlung für internationalen Versand.","fr":"Une première commande PikoBuy se gère plus facilement en plusieurs vérifications. Contrôlez d’abord titre, option vendeur, taille, couleur, images et correspondance du prix avec la variante choisie. Commandez seulement lorsque ces détails sont clairs. Le guide PikoBuy distingue l’achat du paiement ultérieur du transport international.","es":"Un primer pedido PikoBuy es más fácil si se divide en comprobaciones. Revisa título, opción del vendedor, talla, color, imágenes y si el precio corresponde a la variante real. Pide solo cuando todo esté claro. La guía de PikoBuy separa la compra del pago posterior del envío internacional.","it":"Un primo ordine PikoBuy è più semplice dividendolo in controlli. Verifica titolo, opzione del venditore, taglia, colore, immagini e che il prezzo corrisponda alla variante. Ordina solo quando i dettagli sono chiari. La guida PikoBuy distingue l’acquisto dal pagamento successivo della spedizione internazionale.","pt":"Uma primeira encomenda PikoBuy é mais simples dividida em verificações. Confirme título, opção do vendedor, tamanho, cor, imagens e se o preço corresponde à variante. Encomende apenas quando os detalhes estiverem claros. O guia da PikoBuy separa a compra do pagamento posterior do envio internacional.","nl":"Een eerste PikoBuy-bestelling is eenvoudiger met afzonderlijke controles. Controleer titel, verkopersoptie, maat, kleur, afbeeldingen en of de prijs bij de gekozen variant hoort. Bestel pas wanneer dit duidelijk is. De PikoBuy-gids scheidt de aankoop van de latere betaling voor internationale verzending.","pl":"Pierwsze zamówienie PikoBuy łatwiej podzielić na kontrole. Sprawdź tytuł, opcję sprzedawcy, rozmiar, kolor, zdjęcia i czy cena dotyczy wybranego wariantu. Zamów dopiero po wyjaśnieniu szczegółów. Poradnik PikoBuy oddziela zakup od późniejszej płatności za wysyłkę międzynarodową.","sv":"En första PikoBuy-beställning blir enklare med separata kontroller. Kontrollera titel, säljarens alternativ, storlek, färg, bilder och om priset gäller den valda varianten. Beställ först när uppgifterna är tydliga. PikoBuys guide skiljer köpet från den senare betalningen för internationell frakt."},"When an item enters the warehouse, compare the visible QC photos with your saved source record. Look for the selected option, obvious damage and expected accessories. If there is a meaningful mismatch, read the current returns terms immediately; the published policy describes a five-day, 120-hour window for qualifying in-warehouse items. Do not wait until the parcel has already been submitted.":{"de":"Vergleiche beim Lagereingang die sichtbaren QC-Fotos mit deinen gespeicherten Quelldaten. Achte auf die gewählte Variante, offensichtliche Schäden und erwartetes Zubehör. Bei einer relevanten Abweichung sofort die aktuellen Rückgabebedingungen lesen; die veröffentlichte Richtlinie nennt für geeignete Lagerartikel fünf Tage beziehungsweise 120 Stunden. Warte nicht bis nach Paketeinreichung.","fr":"À l’entrée en entrepôt, comparez les photos QC visibles à vos données source. Vérifiez variante choisie, dommages évidents et accessoires attendus. En cas d’écart important, consultez immédiatement les conditions de retour : la politique publiée mentionne cinq jours ou 120 heures pour les articles admissibles en entrepôt. N’attendez pas la soumission du colis.","es":"Cuando llegue al almacén, compara las fotos QC visibles con el registro original. Comprueba variante, daños evidentes y accesorios esperados. Si hay una diferencia importante, consulta inmediatamente las condiciones de devolución: la política publicada indica cinco días o 120 horas para artículos elegibles en almacén. No esperes a enviar el paquete.","it":"All’arrivo in magazzino confronta le foto QC visibili con i dati originali. Controlla variante, danni evidenti e accessori previsti. In caso di differenza importante consulta subito i termini di reso: la politica pubblicata indica cinque giorni o 120 ore per articoli idonei in magazzino. Non attendere l’invio del pacco.","pt":"Quando chegar ao armazém, compare as fotos QC visíveis com o registo original. Verifique variante, danos evidentes e acessórios esperados. Se houver diferença importante, consulte de imediato as condições de devolução: a política publicada indica cinco dias ou 120 horas para artigos elegíveis em armazém. Não espere até submeter o pacote.","nl":"Vergelijk bij aankomst in het magazijn de zichtbare QC-foto’s met je opgeslagen brongegevens. Let op gekozen optie, duidelijke schade en verwachte accessoires. Lees bij een belangrijk verschil direct het actuele retourbeleid: de gepubliceerde regeling noemt vijf dagen of 120 uur voor geschikte magazijnartikelen. Wacht niet tot het pakket is ingediend.","pl":"Po przyjęciu do magazynu porównaj widoczne zdjęcia QC z zapisanymi danymi źródłowymi. Sprawdź wariant, oczywiste uszkodzenia i oczekiwane akcesoria. Przy istotnej różnicy natychmiast przeczytaj warunki zwrotu: opublikowana polityka podaje pięć dni lub 120 godzin dla kwalifikujących się produktów w magazynie. Nie czekaj do nadania paczki.","sv":"När varan kommer till lagret, jämför synliga QC-bilder med dina sparade källuppgifter. Kontrollera vald variant, uppenbara skador och förväntade tillbehör. Läs genast aktuella returvillkor vid en viktig skillnad: den publicerade policyn anger fem dagar eller 120 timmar för berättigade lagervaror. Vänta inte tills paketet har lämnats in."},"For shipping, use the calculator with the real destination, weight and dimensions. Choose an available route by its displayed conditions rather than a generic “best line” recommendation. Review the complete address, declaration requirements, prohibited-item guidance and the total shown at the point of submission. Tracking may appear after dispatch rather than at the moment an order is created.":{"de":"Nutze für den Versand den Rechner mit tatsächlichem Zielort, Gewicht und Maßen. Wähle eine verfügbare Route anhand ihrer Bedingungen statt einer allgemeinen Empfehlung zur „besten Linie“. Prüfe vollständige Adresse, Deklarationsanforderungen, verbotene Waren und die angezeigte Gesamtsumme. Tracking kann erst nach Versand erscheinen, nicht schon bei Bestellerstellung.","fr":"Pour l’expédition, utilisez le calculateur avec destination, poids et dimensions réels. Choisissez une ligne disponible selon ses conditions plutôt qu’une recommandation générique de « meilleure ligne ». Vérifiez adresse complète, déclaration, articles interdits et total affiché. Le suivi peut apparaître après expédition, pas dès la création de commande.","es":"Para enviar, usa el calculador con destino, peso y dimensiones reales. Elige una ruta disponible por sus condiciones, no por una recomendación genérica de «mejor línea». Revisa dirección completa, declaración, artículos prohibidos y total mostrado. El seguimiento puede aparecer tras el envío, no al crear el pedido.","it":"Per la spedizione usa il calcolatore con destinazione, peso e dimensioni reali. Scegli una rotta disponibile in base alle condizioni, non a un generico consiglio sulla «migliore linea». Controlla indirizzo completo, dichiarazione, articoli vietati e totale mostrato. Il tracciamento può apparire dopo la spedizione, non alla creazione dell’ordine.","pt":"Para enviar, use o calculador com destino, peso e dimensões reais. Escolha uma rota disponível pelas suas condições, não por uma recomendação genérica de «melhor linha». Verifique morada completa, declaração, artigos proibidos e total apresentado. O rastreio pode surgir após o envio, não ao criar a encomenda.","nl":"Gebruik voor verzending de calculator met werkelijke bestemming, gewicht en afmetingen. Kies een beschikbare route op basis van de voorwaarden, niet op basis van een algemene aanbeveling voor de “beste lijn”. Controleer volledig adres, aangiftevereisten, verboden artikelen en getoond totaal. Tracking kan pas na verzending verschijnen, niet bij aanmaken van de bestelling.","pl":"Do wysyłki użyj kalkulatora z rzeczywistym celem, wagą i wymiarami. Wybierz dostępną trasę według jej warunków, nie ogólnej rekomendacji „najlepszej linii”. Sprawdź pełny adres, deklarację, towary zabronione i pokazaną sumę. Śledzenie może pojawić się po wysyłce, a nie przy utworzeniu zamówienia.","sv":"Använd kalkylatorn med faktisk destination, vikt och mått inför frakten. Välj en tillgänglig rutt efter dess villkor, inte ett allmänt råd om ”bästa linjen”. Kontrollera fullständig adress, deklarationskrav, förbjudna varor och visat totalbelopp. Spårning kan visas efter avsändning, inte när beställningen skapas."}};
function staticText(source,lang,node){
  if(lang==='en')return source;
  const exactGuide=exactGuideParagraphs[source]?.[lang];
  if(exactGuide)return exactGuide;
  // Retain the actual source text until a faithful translation is available.
  // Topic-based substitutions can otherwise change the meaning of an article.
  const articleElement = node?.nodeType === 1 ? node : node?.parentElement;
  if(articleElement?.closest?.('article.article p:not(.keywords)'))return source;
  const copyKey=Object.keys(copy.en).find(key=>copy.en[key]===source);
  if(copyKey&&copy[lang]?.[copyKey])return copy[lang][copyKey];
  const category=(categoryNames[lang]||{})[source];
  if(category)return category;
  const direct=(staticPhrases[lang]||{})[source];
  if(direct)return direct;
  const fixed=localizeProductText(source,lang);
  if(fixed!==source)return fixed;
  const listing=localizeListingText(source,lang);
  if(listing!==source)return listing;
  const checklist=localizeChecklistText(source,lang);
  if(checklist!==source)return checklist;
  return localTopicText(source,lang,node);
}
function localizeProductText(source,lang){
  const ui=productUi[lang];
  if(!ui)return source;
  const exact={
    '← Back to products':ui.backProducts,'← Back to category':ui.backCategory,
    'Only distinct source images are shown. Repeated images are not used.':ui.onlyDistinct,
    'Product media':ui.productMedia,'Selectable Weidian image thumbnails':ui.selectable,
    'Buy with PikoBuy ↗':ui.buy,
    'View product →':ui.view,
    'View product details →':ui.viewDetails,
    'Independent PikoBuy spreadsheet discovery and product-guide project.':ui.footer,
    '6 verified QC images':`6 ${ui.verifiedQc}`
  }[source];
  if(exact)return exact;
  let match=source.match(/^(\d+) unique Weidian source images?$/i);
  if(match)return `${match[1]} ${ui.unique}`;
  match=source.match(/^(\d+) distinct source images?$/i);
  if(match)return `${match[1]} ${ui.distinct}`;
  match=source.match(/^Show Weidian image (\d+) of (\d+)$/);
  if(match)return `${ui.show} ${match[1]} / ${match[2]}`;
  match=source.match(/^Weidian image (\d+) of (\d+)$/);
  if(match)return `${ui.weidianImage} ${match[1]} / ${match[2]}`;
  match=source.match(/^(.*) Weidian image$/);
  if(match)return `${match[1]} ${ui.weidianImage}`;
  match=source.match(/^(.*) original Weidian image (\d+) of (\d+)$/);
  if(match)return `${match[1]} ${ui.originalImage} ${match[2]} / ${match[3]}`;
  return source;
}
function applyProductLabels(lang){
  const labels=productLabels[lang];
  if(!labels)return;
  collectTranslatables().forEach(entry=>{
    if(entry.kind!=='text')return;
    const source=entry.source.text;
    const exact={
      'Weidian image set':labels.imageSet,
      '6 Weidian fallback images':labels.fallback,
      'QC photo set':labels.qcSet,
      'QC unavailable':labels.qcUnavailable,
      'Weidian original image sequence':labels.sequence,
      'Source images unavailable':labels.sourceUnavailable,
      'All Products':labels.allProducts
    }[source];
    const translated=localizeProductText(exact||source.replace('Product ID',labels.productId).replace('Weidian ID',labels.weidianId),lang);
    if(translated!==source)entry.node.nodeValue=`${entry.source.before}${translated}${entry.source.after}`;
  });
  document.querySelectorAll('[aria-label],[alt]').forEach(element=>{
    const saved=originalAttributes.get(element);
    if(!saved)return;
    ['aria-label','alt'].forEach(attribute=>{
      if(saved[attribute])element.setAttribute(attribute,localizeProductText(saved[attribute],lang));
    });
  });
}

const guideDetails={"how-it-works":{"en":"Before ordering, save the source link, seller, selected colour and size together. Check the option and the current price again at checkout; the spreadsheet is a discovery aid and does not place the order.","de":"Speichere vor der Bestellung den Quelllink, den Verkäufer sowie Farbe und Größe. Prüfe Variante und aktuellen Preis beim Bezahlen erneut; das Spreadsheet hilft bei der Suche und gibt keine Bestellung auf.","fr":"Avant la commande, enregistrez le lien source, le vendeur, la couleur et la taille. Vérifiez à nouveau l’option et le prix au paiement : le tableur facilite la recherche, mais ne passe pas commande.","es":"Antes de pedir, guarda el enlace original, el vendedor, el color y la talla. Comprueba de nuevo la opción y el precio al pagar; la hoja ayuda a buscar, pero no realiza el pedido.","it":"Prima di ordinare, salva il link originale, il venditore, il colore e la taglia. Ricontrolla opzione e prezzo al pagamento: il foglio aiuta nella ricerca, ma non effettua l’ordine.","pt":"Antes de encomendar, guarde a ligação original, o vendedor, a cor e o tamanho. Confirme novamente a opção e o preço no pagamento; a folha ajuda na pesquisa, mas não faz a encomenda.","nl":"Bewaar vóór de bestelling de bronlink, verkoper, gekozen kleur en maat. Controleer de optie en actuele prijs opnieuw bij het afrekenen; het spreadsheet helpt zoeken, maar plaatst geen bestelling.","pl":"Przed zamówieniem zapisz link źródłowy, sprzedawcę, kolor i rozmiar. Przy płatności ponownie sprawdź wariant i aktualną cenę; arkusz pomaga w wyszukiwaniu, lecz nie składa zamówienia.","sv":"Spara källänken, säljaren, vald färg och storlek före beställningen. Kontrollera variant och aktuellt pris igen vid betalning; kalkylbladet hjälper dig att hitta produkter men lägger ingen order."},"qc-photos":{"en":"For shoes, compare the pair, sole and size label; for clothing, check the front, back, seams and a measurement photo when available. Ask for a clearer image if an important detail is hidden. Photos cannot prove authenticity or long-term durability.","de":"Vergleiche bei Schuhen Paar, Sohle und Größenetikett; prüfe bei Kleidung Vorder- und Rückseite, Nähte und gegebenenfalls ein Maßfoto. Fordere ein klareres Bild an, wenn ein wichtiges Detail verdeckt ist. Fotos beweisen weder Echtheit noch Haltbarkeit.","fr":"Pour les chaussures, comparez la paire, la semelle et l’étiquette de taille ; pour les vêtements, vérifiez l’avant, l’arrière, les coutures et une photo des mesures si disponible. Demandez une image plus claire si un détail manque. Les photos ne prouvent ni l’authenticité ni la durabilité.","es":"En el calzado, compara el par, la suela y la etiqueta de talla; en la ropa, revisa el frente, la espalda, las costuras y las medidas si hay una foto. Pide una imagen más clara si falta un detalle importante. Las fotos no prueban autenticidad ni durabilidad.","it":"Per le scarpe confronta il paio, la suola e l’etichetta della misura; per i vestiti controlla davanti, dietro, cuciture e foto delle misure se disponibili. Chiedi un’immagine più chiara se un dettaglio è nascosto. Le foto non provano autenticità o durata.","pt":"No calçado, compare o par, a sola e a etiqueta do tamanho; no vestuário, verifique frente, costas, costuras e fotografia das medidas, quando disponível. Peça uma imagem mais clara se faltar um detalhe importante. As fotos não provam autenticidade nem durabilidade.","nl":"Vergelijk bij schoenen het paar, de zool en het maatlabel; controleer bij kleding de voor- en achterkant, naden en zo mogelijk een meetfoto. Vraag een duidelijkere foto als een belangrijk detail ontbreekt. Foto’s bewijzen geen echtheid of duurzaamheid.","pl":"Przy butach porównaj parę, podeszwę i metkę z rozmiarem; przy ubraniach sprawdź przód, tył, szwy i dostępne zdjęcie pomiarów. Poproś o wyraźniejsze zdjęcie, jeśli ważny szczegół jest niewidoczny. Zdjęcia nie potwierdzają autentyczności ani trwałości.","sv":"Jämför paret, sulan och storleksetiketten för skor. Kontrollera fram- och baksida, sömmar och en måttbild om sådan finns för kläder. Be om en tydligare bild om en viktig detalj saknas. Bilder bevisar inte äkthet eller hållbarhet."},"shipping-cost":{"en":"Record the destination, item type, estimated packed weight and all three parcel dimensions before comparing routes. Review the final quote and any applicable taxes or fees at checkout; an item price alone is not the delivered total.","de":"Notiere Zielland, Warenart, geschätztes verpacktes Gewicht und alle drei Paketmaße, bevor du Versandwege vergleichst. Prüfe beim Bezahlen den endgültigen Preis sowie mögliche Steuern und Gebühren; der Artikelpreis allein ist nicht der Gesamtpreis.","fr":"Notez le pays de destination, le type d’article, le poids emballé estimé et les trois dimensions avant de comparer les itinéraires. Vérifiez le montant final et les taxes ou frais applicables au paiement : le prix de l’article ne représente pas le coût livré.","es":"Anota el destino, el tipo de artículo, el peso estimado embalado y las tres dimensiones antes de comparar rutas. Revisa el importe final y los impuestos o cargos aplicables al pagar; el precio del producto no es el coste total entregado.","it":"Annota destinazione, tipo di articolo, peso imballato stimato e tre dimensioni prima di confrontare le rotte. Verifica al pagamento il preventivo finale e le eventuali imposte o spese: il prezzo del prodotto non è il costo totale consegnato.","pt":"Registe destino, tipo de artigo, peso embalado estimado e as três dimensões antes de comparar rotas. Confirme o valor final e eventuais impostos ou taxas no pagamento; o preço do artigo não é o custo total entregue.","nl":"Noteer bestemming, producttype, geschat verpakt gewicht en alle drie de afmetingen voordat je routes vergelijkt. Controleer bij het afrekenen de definitieve prijs en eventuele belastingen of kosten; de productprijs is niet het totaalbedrag thuisbezorgd.","pl":"Przed porównaniem tras zapisz kraj docelowy, rodzaj produktu, szacowaną wagę po zapakowaniu i trzy wymiary paczki. Przy płatności sprawdź końcową wycenę oraz ewentualne podatki i opłaty; cena produktu nie jest całkowitym kosztem dostawy.","sv":"Notera destination, produkttyp, uppskattad packad vikt och paketets tre mått innan du jämför fraktvägar. Kontrollera slutpriset och eventuella skatter eller avgifter vid betalningen; produktpriset är inte hela kostnaden för leveransen."},"sizing":{"en":"Compare the seller’s measurements with a similar garment that fits you, using the same measuring method. For shoes, check the seller’s size system and insole measurement when supplied; request a measurement photo if the choice is unclear.","de":"Vergleiche die Maße des Verkäufers mit einem gut passenden Kleidungsstück und verwende dieselbe Messmethode. Prüfe bei Schuhen das Größensystem und, falls angegeben, die Innensohlenlänge; bitte bei Unklarheiten um ein Maßfoto.","fr":"Comparez les mesures du vendeur à un vêtement similaire qui vous va, en utilisant la même méthode. Pour les chaussures, vérifiez le système de tailles et la longueur de semelle intérieure si elle est indiquée ; demandez une photo de mesure en cas de doute.","es":"Compara las medidas del vendedor con una prenda similar que te quede bien, usando el mismo método. Para calzado, comprueba el sistema de tallas y la longitud de la plantilla si se indica; pide una foto de la medida si tienes dudas.","it":"Confronta le misure del venditore con un capo simile che ti veste bene, usando lo stesso metodo. Per le scarpe controlla il sistema di taglie e la lunghezza della soletta, se indicata; chiedi una foto della misura in caso di dubbio.","pt":"Compare as medidas do vendedor com uma peça semelhante que lhe sirva bem, usando o mesmo método. No calçado, confirme o sistema de tamanhos e o comprimento da palmilha, se indicado; peça uma fotografia da medida em caso de dúvida.","nl":"Vergelijk de maten van de verkoper met een vergelijkbaar kledingstuk dat goed past en gebruik dezelfde meetmethode. Controleer bij schoenen het maatsysteem en eventueel de lengte van de binnenzool; vraag bij twijfel om een meetfoto.","pl":"Porównaj wymiary sprzedawcy z podobnym ubraniem, które dobrze pasuje, używając tej samej metody pomiaru. Przy butach sprawdź system rozmiarów i podaną długość wkładki; w razie wątpliwości poproś o zdjęcie pomiaru.","sv":"Jämför säljarens mått med ett liknande plagg som passar dig och använd samma mätmetod. För skor, kontrollera storlekssystemet och innersulans längd om den anges; be om en måttbild om du är osäker."}};
